import type { D1AuthoredBank } from '../corpus'

export const PESISIR_UTARA_D_R3: D1AuthoredBank = {
  universeId: 'pesisir-utara',
  rubricId: 'D-R3',
  STRONG: [
    { chapters: [
      { chapterNumber: 33, title: 'Daftar Jalur Disalin', paragraphs: ['Sari menyalin daftar jalur garam ketika dua petugas loket mengukur lemari arsip. Seorang petugas meminta kunci cadangan, tetapi Bu Hasnah mengatakan kunci itu patah. Menjelang sore, lemari masih dapat dibuka dari gudang. Sari menyelipkan salinannya ke bawah alas peti ikan asin sebelum pulang.'] },
      { chapterNumber: 34, title: 'Kunci Gudang Ditukar', paragraphs: ['Pagi berikutnya, gembok baru menggantung pada pintu gudang dan kuncinya dibawa kepala loket. Bu Hasnah harus meminta izin setiap kali buruh mengambil karung. Antrean gerobak mencapai jalan batu. Sari masuk bersama rombongan pertama, lalu menyembunyikan buku muatan lama di balik susunan tali temali.'] },
      { chapterNumber: 35, title: 'Cap Biru Wajib', paragraphs: ['Regent Damar memerintahkan cap lilin biru pada seluruh manifest sebelum penimbangan. Pak Uweng menolak satu lembar karena nama awak ditulis sebagai barang. Petugas mengambil pena Sari dan menyuruhnya menyalin ulang. Ia memilih membiarkan kapal menunggu, sementara nakhoda mulai menghitung biaya tambat di depan para buruh.'] },
      { chapterNumber: 36, title: 'Tambat Dibayar Harian', paragraphs: ['Kantor izin menagih biaya tambat per hari untuk kapal yang manifestnya belum bercap. Nakhoda menyerahkan tagihan kepada Bu Hasnah, lalu mengancam memindahkan muatan garam ke pelabuhan timur. Sari hanya punya satu pagi untuk menemukan daftar awak asli sebelum gudang kehilangan pesanan sebulan.'] },
      { chapterNumber: 37, title: 'Lorong Arsip Dipagari', paragraphs: ['Pagar bambu dipasang melintang di lorong arsip, dijaga petugas yang mengenali tulisan tangan Sari. Ia mencoba masuk membawa kendi minyak lampu, namun disuruh meletakkannya di luar. Malam itu Sari memanjat jendela gudang; bunyi peluit memaksanya turun tanpa daftar, meninggalkan sandal pada kusen.'] },
      { chapterNumber: 38, title: 'Sandal Menjadi Bukti', paragraphs: ['Sandal Sari dipajang di meja loket bersama pengumuman pencarian pemilik. Damar menawarkan pengembaliannya bila ia menyerahkan salinan daftar jalur. Sari berjalan tanpa alas melewati papan dermaga yang dipenuhi serpih karat dan menolak mengaku. Sebelum petang, petugas mendatangi rumah Bu Hasnah untuk mencari pasangan sandal tersebut.'] },
      { chapterNumber: 39, title: 'Rumah Hasnah Digeledah', paragraphs: ['Tiga petugas membongkar peti pakaian Bu Hasnah dan menyita buku sewa gudang. Mereka tidak menemukan daftar jalur, tetapi membawa surat izin usaha sebagai jaminan. Damar memberi waktu sampai lonceng siang berbunyi esok. Tanpa surat itu, satu pintu gudang harus ditutup dan separuh buruh dipulangkan.'] },
      { chapterNumber: 40, title: 'Pintu Timur Ditutup', paragraphs: ['Lonceng siang berbunyi tanpa penyerahan salinan. Petugas merantai pintu timur gudang saat gerobak garam masih berbaris. Bu Hasnah memilih enam buruh yang boleh bertahan; sebelas lainnya pulang tanpa upah. Sari memindahkan buku tersembunyi ke balik bajunya karena lorong tali akan dibongkar malam itu.'] },
      { chapterNumber: 41, title: 'Aturan Sahkan Ganda', paragraphs: ['Regent Damar menempel pengumuman bahwa tiap berkas muatan wajib disahkan ulang di loket izin sebelum derek bergerak. Sari masih dapat menulis angka jujur, hanya saja setiap lembar kini melewati meja orang itu. Waktu tunggu bertambah dua jam. Ruang bagi angka yang tidak cocok menyempit, sebab siapa pun yang membawa berkas terlambat harus menjelaskan keterlambatannya di depan loket.'] },
      { chapterNumber: 42, title: 'Derek Menunggu Stempel', paragraphs: ['Derek berhenti dengan peti tergantung karena lembar Sari belum mendapat pengesahan kedua. Pengawas memberi pilihan: ubah jumlah awak menjadi nol atau turunkan seluruh muatan. Ia menurunkan peti, dan tali pengangkat merusak tiga keranjang ikan. Pemiliknya menuntut ganti sebelum matahari tenggelam.'] },
      { chapterNumber: 43, title: 'Giliran Malam Dihapus', paragraphs: ['Giliran timbang malam dihapus, dan seluruh bongkaran dipindah ke siang saat halaman dermaga penuh pengawas. Satu-satunya jam sepi milik Sari lenyap. Ia menahan berkas garam sehari untuk mencari saksi, lalu kapal berangkat tanpa muatan itu, dan Bu Hasnah menanggung denda gudang penuh. Menunda kini punya harga yang dibayar orang lain, bukan sekadar rasa takut.'] },
      { chapterNumber: 44, title: 'Denda Memakan Upah', paragraphs: ['Bu Hasnah membayar denda dengan upah buruh yang belum dibagikan. Orang-orang mengepung meja Sari sambil menunjukkan telapak berkapur garam. Damar mengirim pesan bahwa denda berikutnya menjadi dua kali lipat. Sari harus membuka buku pribadi kepada mereka malam itu atau menghadapi gudang kosong keesokan pagi.'] },
      { chapterNumber: 45, title: 'Perahu Pengantar Diperiksa', paragraphs: ['Sari menitipkan buku kepada Latif, tetapi perahu pengantar dihentikan sebelum melewati pemecah ombak. Penjaga memeriksa karcis, bekal, bahkan gulungan layar. Latif membuang bungkusan ke air dangkal agar tidak ditemukan. Arus membawanya ke kisi pintu pasang, tempat petugas berjaga sejak fajar.'] },
      { chapterNumber: 46, title: 'Penjaga Pintu Pasang', paragraphs: ['Dua penjaga berdiri di pintu air pasang membawa surat perintah: seluruh buku muatan tidak resmi harus diserahkan sebelum air naik petang ini, atau gudang garam disegel dan pekerjanya dipulangkan. Sari memegang buku pribadinya di balik baju. Pilihan tinggal dua, menyerahkan atau membawanya keluar dermaga, sementara setiap jam menaikkan risiko orang yang menampungnya.'] },
      { chapterNumber: 47, title: 'Jalan Darat Diblokir', paragraphs: ['Sari berlari ke jalan darat, namun gerobak kantor izin menutup jembatan kayu. Petugas memeriksa bakul warga satu per satu. Dari belakang terdengar palu memasang papan segel gudang. Ia berbalik menuju menara suar, satu-satunya tempat tinggi yang dapat dijangkau sebelum pasang menutup tangga batu.'] },
      { chapterNumber: 48, title: 'Tangga Suar Dikepung', paragraphs: ['Empat petugas mengepung kaki menara dan menjanjikan pembukaan gudang bila buku dijatuhkan. Air sudah menutup separuh undakan. Sari merobek halaman nama awak, memasukkannya ke botol minyak, lalu melempar botol ke arah perahu Latif. Petugas mulai menaiki tangga sambil membawa borgol.'] },
      { chapterNumber: 49, title: 'Botol Tersangkut Jaring', paragraphs: ['Botol tersangkut pada jaring nelayan sebelum mencapai Latif. Seorang penjaga mengarungi air untuk mengambilnya, sementara Sari menahan pintu menara dengan batang besi. Latif memotong jaring dari perahu dan menerima botol. Damar memerintahkan penahanan Bu Hasnah bila halaman nama awak tidak diserahkan ke loket sebelum malam.'] },
      { chapterNumber: 50, title: 'Nama Dibaca Terbuka', paragraphs: ['Latif membawa botol ke kapal pemeriksa yang baru masuk teluk. Sari turun saat petugas mendobrak pintu menara dan membaca salinan nama awak di hadapan buruh. Bu Hasnah dibebaskan dari gerobak tahanan, tetapi gudangnya tetap tersegel. Para buruh mengumpulkan upah terakhir untuk menyewa halaman timbang mandiri.'] },
    ], justification: 'Across Bab 33–50, Damar takes the archive key, closes a warehouse door, imposes double approval, removes night weighing, and surrounds every exit. Delay costs dock fees, damaged goods, wages, and arrests before Sari sends the crew names through the tide.' },
    { chapters: [
      { chapterNumber: 33, title: 'Tali Sandar Dihitung', paragraphs: ['Petugas kantor izin menghitung simpul pada tali sandar yang dipegang Latif, lalu mencatat satu simpul longgar. Biasanya teguran selesai dengan perbaikan di tempat. Kali ini catatan dibawa pergi. Sari melihat cap biru di sudutnya dan meminta Latif menyimpan karcis feri sebagai bukti jam kedatangan.'] },
      { chapterNumber: 34, title: 'Karcis Pagi Ditahan', paragraphs: ['Karcis feri Latif ditahan petugas sebelum ia naik ke geladak. Mereka mengatakan pemeriksaan simpul belum selesai, sehingga ia kehilangan keberangkatan pagi dan separuh upah. Sari datang membawa buku sandar, tetapi penjaga hanya menerima salinan yang disahkan loket Damar. Loket itu mendadak tutup hingga esok.'] },
      { chapterNumber: 35, title: 'Upah Pertama Hilang', paragraphs: ['Latif menunggu di bangku dermaga ketika feri kedua berangkat tanpa dirinya. Mandor memotong upah sehari penuh karena dua trayek terlewat. Sari menawarkan uang belanja, namun adiknya menolak dan menunjukkan tagihan obat ibu. Mereka harus memperoleh pengesahan sebelum apotek menutup pada petang berikutnya.'] },
      { chapterNumber: 36, title: 'Loket Meminta Pengakuan', paragraphs: ['Damar membuka loket sendiri dan menyodorkan pernyataan bahwa Latif mengabaikan keselamatan kapal. Pengesahan buku sandar akan diberikan setelah tanda tangan. Latif memegang pena, lalu Sari menarik lembar itu. Mereka pulang tanpa cap, sementara apotek menyerahkan hanya separuh obat sesuai uang yang tersisa.'] },
      { chapterNumber: 37, title: 'Jatah Feri Dikurangi', paragraphs: ['Nama Latif kembali ke papan, tetapi hanya untuk satu trayek pendek setiap dua hari. Kepala sandar menunjuk surat pengakuan kosong sebagai alasan. Sari mencari awak yang melihat simpul tersebut; dua orang bersedia bicara setelah giliran selesai. Sore harinya keduanya dipindah ke kapal lain.'] },
      { chapterNumber: 38, title: 'Saksi Naik Kapal Asing', paragraphs: ['Kapal pengangkut membawa dua saksi keluar teluk sebelum Sari sempat meminta tanda tangan. Latif mengejar dengan perahu kecil, namun penjaga merampas dayungnya di ujung dermaga. Damar mengembalikan dayung dengan syarat buku sandar diserahkan malam itu. Tanpa perahu, Latif tidak dapat mengambil trayek tersisa besok.'] },
      { chapterNumber: 39, title: 'Perahu Dirantai Kantor', paragraphs: ['Rantai kantor melilit perahu Latif, dan kuncinya tergantung di pinggang kepala sandar. Sari meminjam perahu Nyi Ratih untuk mengantarnya bekerja. Petugas mencatat nomor lambung pinjaman, lalu memberi peringatan bahwa setiap pemilik yang membantu akan kehilangan tempat tambat. Nyi Ratih meminta perahunya kembali sebelum siang.'] },
      { chapterNumber: 40, title: 'Tambatan Menolak Latif', paragraphs: ['Tidak satu pun pemilik perahu berani mengantar Latif setelah surat peringatan beredar. Ia berjalan pulang membawa tali kerja di bahu. Kepala sandar menaruh satu amplop di rumah: besok ia boleh kembali jika Sari menyerahkan buku asli. Sari membakar amplop, tetapi menyimpan potongan capnya.'] },
      { chapterNumber: 41, title: 'Surat Teguran Latif', paragraphs: ['Latif menerima surat teguran karena dianggap lambat mengikat tali sandar, meski catatan sandar hari itu tercepat sepanjang bulan. Sari membaca surat tersebut di serambi rumah dan mengenali gaya penulisan loket izin. Adiknya masih bekerja seperti biasa. Namun teguran tertulis membuat setiap kesalahan kecil berikutnya dapat dipakai tanpa perlu alasan baru.'] },
      { chapterNumber: 42, title: 'Kesalahan Tali Dicatat', paragraphs: ['Seutas tali lapuk putus di tangan awak lain, tetapi kepala sandar menulis nama Latif pada laporan. Sari menunjukkan karcis yang membuktikan adiknya berada di feri seberang saat kejadian. Petugas menyita karcis itu untuk pemeriksaan. Latif diperintah mengambil giliran malam sambil menunggu keputusan.'] },
      { chapterNumber: 43, title: 'Trayek Pindah Gelap', paragraphs: ['Trayek Latif dipindah ke penyeberangan tengah malam, jalur berkarang yang biasanya diberikan kepada awak berpengalaman. Ia pulang dengan telapak lecet dan mata merah. Sari menahan berkas keberatan selama tiga hari agar tidak memancing perhatian, lalu jadwal berkarang itu ditetapkan permanen. Diamnya berubah menjadi kerugian yang menempel pada tubuh adiknya.'] },
      { chapterNumber: 44, title: 'Karang Merobek Lambung', paragraphs: ['Lambung feri tergores karang pada malam ketiga. Pemilik kapal menagih biaya tambal kepada seluruh awak, meski juru mudi mengaku salah membaca lampu. Bagian Latif setara dua pekan upah. Damar menawarkan menghapus tagihan jika Sari membawa manifest kosong sebelum rapat pelabuhan.'] },
      { chapterNumber: 45, title: 'Rapat Tanpa Pembela', paragraphs: ['Sari datang ke rapat tanpa manifest yang diminta. Kepala sandar mengeluarkan karcis sitaan dan merobeknya di depan saksi. Latif dikeluarkan dari jadwal sampai biaya lambung lunas. Jika mereka menjual perahu keluarga, utang terbayar; bila menunggu upah lain, obat ibu habis dahulu.'] },
      { chapterNumber: 46, title: 'Izin Layar Digantung', paragraphs: ['Izin melaut Latif digantung, dan pemulihannya dikaitkan pada satu syarat tertulis: Sari harus mengesahkan berkas muatan kosong sebelum pasang esok pagi. Regent Damar menyerahkan lembar itu langsung ke tangannya. Menolak berarti adiknya berhenti melaut, menerima berarti angka palsu memakai namanya, dan tidak ada jalur ketiga yang tersisa sampai pasang.'] },
      { chapterNumber: 47, title: 'Perahu Keluarga Ditawar', paragraphs: ['Pedagang besi datang atas suruhan kantor untuk menawar perahu keluarga senilai utang tambal. Latif hampir menerima karena batas pengesahan tinggal beberapa jam. Sari mencabut papan nama perahu dan membawanya ke balai awak, berharap pemilik kapal lain mengakui catatan trayek malam.'] },
      { chapterNumber: 48, title: 'Balai Awak Dikunci', paragraphs: ['Pintu balai awak terkunci dan daftar anggotanya sudah dibawa ke loket. Dua nelayan berbicara melalui jendela, lalu menolak menandatangani setelah penjaga mendekat. Latif menyerahkan surat izin kepada Sari dan berjalan ke pasar mencari kerja angkut. Damar memberi satu jam terakhir sebelum pasang.'] },
      { chapterNumber: 49, title: 'Lonceng Pasang Berbunyi', paragraphs: ['Saat lonceng pasang berbunyi, Sari menulis penolakan di bawah syarat Damar dan menempel potongan cap amplop sebagai pembanding. Petugas menyita izin Latif. Pedagang besi menarik perahu dari tambatan, tetapi Nyi Ratih melilitkan rantai penutup lapaknya pada tiang haluan hingga buruh sempat menyalin surat tersebut.'] },
      { chapterNumber: 50, title: 'Trayek Baru Patungan', paragraphs: ['Para buruh membaca salinan penolakan di halaman timbang. Tiga pemilik perahu menarik diri dari jadwal kantor dan mengumpulkan bahan bakar untuk trayek patungan. Latif berlayar sebagai awak tanpa izin Damar, dengan upah lebih kecil dan rute memutar. Perahu keluarga tetap terjual untuk melunasi obat serta utang lambung.'] },
    ], justification: 'Bab 33–50 turns one rope notation into withheld tickets, lost wages, chained boats, vanished witnesses, a dangerous permanent route, hull debt, and suspension. Damar finally conditions Latif’s livelihood on Sari signing a false empty manifest before the tide.' },
    { chapters: [
      { chapterNumber: 33, title: 'Kaleng Uang Ditakar', paragraphs: ['Nyi Ratih menuangkan isi kaleng uang ke meja warung dan memisahkan sewa, beras, serta minyak lampu. Seorang penagih kantor izin melihat tumpukan itu sambil memesan kopi. Sebelum pergi, ia mengukur lebar lapak dengan tali dan membawa catatan ukuran tanpa menjelaskan keperluannya.'] },
      { chapterNumber: 34, title: 'Bangku Kena Pungutan', paragraphs: ['Surat baru menetapkan pungutan untuk setiap bangku yang menghadap dermaga. Nyi Ratih mengangkat dua bangku ke gudang agar tagihan mengecil. Pelanggan berdiri sambil makan, lalu pindah ke warung seberang. Sari menyimpan salinan surat, sementara penagih menjadwalkan pembayaran pertama tiga hari lagi.'] },
      { chapterNumber: 35, title: 'Kompor Disita Sementara', paragraphs: ['Tiga hari berlalu tanpa uang cukup. Penagih membawa kompor minyak sebagai jaminan, menyisakan tungku kecil yang hanya muat satu ceret. Ratih tak bisa menggoreng ikan untuk buruh siang. Ia meminta Sari menulis keberatan sebelum kantor tutup, tetapi petugas menolak lembar tanpa cap pemilik dermaga.'] },
      { chapterNumber: 36, title: 'Cap Pemilik Ditolak', paragraphs: ['Pemilik dermaga memberi cap setelah Ratih membayar ongkos tambahan, namun kantor menyatakan bentuknya kedaluwarsa. Kompor akan dilelang pada akhir pekan. Sari mendatangi gudang sitaan dan melihat lima benda warung lain bertumpuk di sana. Penjaga menawarkan kompor kembali bila Ratih berhenti menerima pertemuan buruh.'] },
      { chapterNumber: 37, title: 'Pertemuan Pindah Dapur', paragraphs: ['Ratih menutup pintu depan, lalu menerima enam buruh di dapur belakang. Mereka mencatat nama awak yang hilang dari manifest. Seorang pelanggan baru meninggalkan kopi utuh dan pergi tergesa. Malamnya, cat merah muncul pada kusen warung bersama angka tunggakan yang dua kali lebih besar.'] },
      { chapterNumber: 38, title: 'Utang Ditempel Terbuka', paragraphs: ['Daftar utang Ratih ditempel di tiang dermaga sehingga pemasok beras menolak memberi tempo. Ia menjual gelang kuningan untuk membeli bahan sehari. Sari ingin membawa catatan awak ke tempat lain, tetapi semua pemilik lapak sudah melihat cat merah. Hanya warung itu yang masih bersedia menyimpan pertemuan.'] },
      { chapterNumber: 39, title: 'Pemasok Menutup Keranjang', paragraphs: ['Pedagang ikan menutup keranjangnya ketika Ratih mendekat dan menunjuk surat larangan menjual kepada penunggak. Warung hanya menyajikan kopi encer. Damar mengirim pesan: lunasi sebelum Senin atau izin dapur dicabut. Sari mengusulkan patungan, namun upah buruh baru saja dipotong biaya tambat.'] },
      { chapterNumber: 40, title: 'Izin Dapur Dicabut', paragraphs: ['Senin pagi, petugas melepas papan izin dapur dan menyegel tungku kecil. Ratih tetap membuka warung untuk air minum gratis. Penjaga menghitung setiap orang yang masuk, lalu mencatat nama mereka. Sari memindahkan catatan lama ke rongga atap sebelum petugas kembali membawa tangga pemeriksaan.'] },
      { chapterNumber: 41, title: 'Sewa Lapak Dinaikkan', paragraphs: ['Sewa lapak Nyi Ratih dinaikkan tiga kali lipat dengan alasan perbaikan lantai dermaga yang belum pernah dikerjakan. Perempuan itu tetap membuka warung sejak subuh dan menghitung sisa uang di kaleng. Sari membantu mengangkat bangku. Kenaikan tersebut belum menutup warung, tetapi memotong tabungan yang selama ini membuat Nyi Ratih berani bicara.'] },
      { chapterNumber: 42, title: 'Lantai Warung Dicongkel', paragraphs: ['Tukang kantor datang mencungkil dua papan lantai sebagai tanda perbaikan. Lubang membuat pelanggan tak dapat mencapai meja belakang. Ratih menutupinya dengan pintu bekas, lalu petugas menagih biaya bahan. Bila tak dibayar besok, seluruh bagian depan akan dibongkar meski sewa bulan berjalan sudah lunas.'] },
      { chapterNumber: 43, title: 'Saluran Air Diputus', paragraphs: ['Saluran air bersih menuju deretan warung diputus, dan satu-satunya penjual air tersisa adalah tangki milik kantor izin. Nyi Ratih terpaksa membeli setiap pagi dengan harga yang ditentukan sepihak. Sari menunggu satu pekan sebelum mencatat harga itu, dan dalam pekan tersebut tabungan kaleng habis. Menunda telah memindahkan beban ke dapur orang lain.'] },
      { chapterNumber: 44, title: 'Tangki Menolak Ember', paragraphs: ['Petugas tangki menolak ember Ratih karena uangnya kurang satu keping. Ia berjalan ke sumur kampung, kehilangan jam sarapan ketika buruh biasa berkumpul. Saat kembali, lembar nama awak di rongga atap basah oleh rembesan. Tinta tiga nama sudah menyebar dan sulit dibaca.'] },
      { chapterNumber: 45, title: 'Saksi Kehilangan Tempat', paragraphs: ['Dua awak datang untuk menandatangani catatan, tetapi warung tak memiliki air untuk menyeduh kopi atau membilas garam dari tangan mereka. Penjaga mengusir keduanya dari bangku bongkaran. Satu awak berjanji kembali lusa; yang lain berangkat malam itu dan tak meninggalkan alamat.'] },
      { chapterNumber: 46, title: 'Bongkar Warung Serentak', paragraphs: ['Surat pembongkaran warung dikeluarkan dengan tanggal yang sama persis dengan kedatangan pemeriksa pusat, sehingga Nyi Ratih harus memilih antara menjaga barang dagangannya atau berdiri sebagai saksi. Sari membaca kedua tanggal itu berulang kali. Menunggu sehari saja berarti kehilangan mulut yang paling berani di dermaga, sekaligus kehilangan atap tempat catatan lama disimpan.'] },
      { chapterNumber: 47, title: 'Atap Dibuka Paksa', paragraphs: ['Tukang memanjat atap sebelum fajar dan melempar genting ke halaman. Sari mengambil lembar catatan dari rongga, namun petugas merampas separuhnya. Ratih mengangkut kaleng, ceret, serta pintu bekas ke gerobak. Pemeriksa akan tiba saat pasang siang; warung harus rata sebelum lonceng pertama.'] },
      { chapterNumber: 48, title: 'Gerobak Dilarang Keluar', paragraphs: ['Gerobak Ratih dihentikan di gerbang karena barang lapak dianggap jaminan tunggakan. Ia meninggalkan ceret dan mendorong sendiri peti catatan menuju jalan kampung. Sari membawa sisa lembar ke kapal pemeriksa. Damar memerintahkan penjaga menutup papan lintasan, memaksa mereka menyeberangi lumpur pasang.'] },
      { chapterNumber: 49, title: 'Kesaksian Tanpa Warung', paragraphs: ['Ratih tiba dengan kaki berdarah ketika pemeriksa mulai menaiki kapal. Ia menyebut nama awak sambil Sari menunjukkan lembar yang selamat. Di belakang mereka, tukang merobohkan tiang terakhir warung. Petugas pusat menerima berkas, tetapi meminta Ratih menetap di kota selama pemeriksaan dan menanggung penginapannya sendiri.'] },
      { chapterNumber: 50, title: 'Tenda Kopi Patungan', paragraphs: ['Buruh mendirikan tenda dari layar robek di luar batas dermaga. Ratih menyalakan kompor pinjaman dan menyimpan surat panggilan kota dalam kaleng kosong. Warung lamanya sudah menjadi tumpukan kayu milik kantor. Sari mengambil bagian belanja rumah dari hasil patungan untuk ongkos Ratih, sehingga beras keluarganya harus menunggu upah berikutnya.'] },
    ], justification: 'From Bab 33 onward, fees consume Ratih’s seating, stove, suppliers, kitchen permit, water, and savings. Demolition is timed against the central inspection, forcing her through a blocked exit and leaving her without a premises after she testifies.' },
    { chapters: [
      { chapterNumber: 33, title: 'Batu Tera Retak', paragraphs: ['Pak Uweng menemukan retak rambut pada batu tera ketika membersihkan garam dari bak timbang. Sari membungkus batu itu dengan kain dan mencatat berat pembanding. Petugas loket datang meminta alat tersebut untuk diperiksa, tetapi Uweng menolak tanpa tanda terima. Mereka pulang membawa nomor sertifikatnya.'] },
      { chapterNumber: 34, title: 'Nomor Sertifikat Dicoret', paragraphs: ['Nomor sertifikat Uweng dicoret dari papan alat sah, meski masa berlakunya masih enam bulan. Kapal pertama menolak hasil timbang dan meninggalkan tiga puluh karung di halaman. Bu Hasnah memberi waktu sampai besok untuk memulihkan nomor, sebab garam terbuka akan menyerap embun malam.'] },
      { chapterNumber: 35, title: 'Karung Menarik Embun', paragraphs: ['Pagi hari, permukaan karung terasa lembap dan beratnya bertambah. Pembeli menurunkan harga untuk seluruh tumpukan, bukan hanya bagian luar. Uweng membawa batu tera ke kantor demi pemeriksaan cepat. Petugas menyimpannya, menyerahkan kuitansi tanpa nomor, lalu berkata hasil baru keluar setelah kapal pembeli berikutnya berangkat.'] },
      { chapterNumber: 36, title: 'Kuitansi Tanpa Nomor', paragraphs: ['Sari menunjukkan kuitansi kosong kepada Damar. Ia menawarkan nomor pemeriksaan bila Uweng menandatangani angka kantor untuk muatan semalam. Juru timbang menolak dan kehilangan akses ke batu teranya. Bu Hasnah menjual garam lembap dengan rugi, kemudian memotong jatah makan gudang untuk menutup selisih.'] },
      { chapterNumber: 37, title: 'Bak Timbang Dipindah', paragraphs: ['Buruh kantor menyeret bak timbang Uweng ke bawah talang bocor dan memagari tempat lamanya. Setiap hujan menambah air pada muatan sebelum ditimbang. Sari mencoba mengukur selisih memakai ember, namun petugas menyita ember sebagai alat tak terdaftar. Kapal berikut menunggu hanya sampai fajar.'] },
      { chapterNumber: 38, title: 'Fajar Membawa Penolakan', paragraphs: ['Hujan berhenti menjelang fajar, tetapi angka kantor melebihi daftar kapal sebanyak enam pikul. Nakhoda membatalkan pembelian dan menagih ongkos perjalanan kepada gudang. Uweng menawarkan rumahnya sebagai jaminan agar buruh tetap menerima upah. Damar mengirim surat bahwa sengketa selesai jika catatan pembanding dimusnahkan.'] },
      { chapterNumber: 39, title: 'Rumah Uweng Dijaminkan', paragraphs: ['Bu Hasnah menerima surat jaminan rumah Uweng dan membayar buruh. Sari menyimpan catatan pembanding di peti kapur. Malamnya, dua petugas mendatangi rumah juru timbang dan mengukur halaman untuk pelelangan. Jika sengketa belum dicabut dalam empat hari, keluarganya harus pindah sebelum pasang besar.'] },
      { chapterNumber: 40, title: 'Peti Kapur Dibuka', paragraphs: ['Petugas menggeledah peti kapur saat Sari berada di loket. Mereka menemukan salinan angka, namun lembar asli sudah dibawa Uweng di balik ikat pinggang. Damar melarangnya bekerja sampai sertifikat diperiksa. Sari mengambil alih bak, meski tanda tangannya tidak diterima pembeli lama.'] },
      { chapterNumber: 41, title: 'Sertifikat Timbangan Diragukan', paragraphs: ['Sertifikat tera timbangan garam dipertanyakan kantor izin, dan Pak Uweng diminta menyerahkan salinan lama yang tersimpan sejak musim kering. Juru timbang tersebut masih menimbang seperti biasa sambil menggerutu. Sari mencatat tanggal permintaan itu. Keraguan resmi terhadap alat membuat setiap angka berat yang ia tulis kehilangan penopang bila diperiksa kemudian.'] },
      { chapterNumber: 42, title: 'Salinan Lama Dirampas', paragraphs: ['Uweng membawa salinan sertifikat ke loket, tetapi petugas merobek bagian tanggal dan menyimpan sisanya. Ia menuntut pengembalian hingga dua penjaga mendorongnya keluar. Sari sempat mengambil potongan tanggal dari lantai. Damar menyatakan potongan tanpa badan surat tak berlaku dan melarang penimbangan esok pagi.'] },
      { chapterNumber: 43, title: 'Timbangan Kantor Disegel', paragraphs: ['Timbangan lama diangkut dan diganti alat bersegel milik kantor izin, sedangkan Pak Uweng dilarang mendekati bak penimbang. Angka berat sekarang keluar dari tangan petugas baru. Sari menahan permintaan penimbangan ulang selama dua hari sambil mencari surat tera, dan pada hari ketiga catatan alat lama dinyatakan hilang dari arsip.'] },
      { chapterNumber: 44, title: 'Selisih Menjadi Utang', paragraphs: ['Alat baru mencatat kelebihan berat pada setiap karung. Kantor menagih pajak selisih kepada Uweng karena namanya masih tertera sebagai penanggung jawab. Jumlahnya setara harga rumah yang dijaminkan. Sari harus menyerahkan potongan sertifikat hari itu atau pelelangan dimajukan ke pagi berikutnya.'] },
      { chapterNumber: 45, title: 'Pelelangan Saat Subuh', paragraphs: ['Sebelum subuh, penawar berkumpul di halaman rumah Uweng. Sari menunjukkan potongan tanggal, tetapi juru lelang menolak menghentikan penjualan. Bu Hasnah membeli kembali rumah itu atas nama keluarga Uweng, tetapi petugas kantor memenangkan sebidang halaman depan dan jalan menuju sumur. Keluarga Uweng menumpuk tikar mereka di gudang garam.'] },
      { chapterNumber: 46, title: 'Uweng Dipanggil Pemalsu', paragraphs: ['Pak Uweng dipanggil sebagai terduga pemalsu berat muatan, dengan sidang dermaga ditetapkan lusa pagi. Bila Sari menunggu sampai pemeriksa pusat tiba pekan depan, juru timbang itu sudah berstatus tersangka dan keterangannya tidak lagi dihitung. Membela lebih awal berarti membuka buku pribadinya di depan Regent Damar tanpa perlindungan siapa pun.'] },
      { chapterNumber: 47, title: 'Buku Pribadi Dibuka', paragraphs: ['Sari membuka buku pribadinya di ruang sidang dan menunjukkan pola selisih sejak alat kantor dipasang. Damar memerintahkan penyitaan buku sebagai barang perkara. Uweng dibebaskan sampai lusa, namun dilarang meninggalkan dermaga. Tanpa salinan lain, pembelaan mereka bergantung pada lembar yang kini terkunci.'] },
      { chapterNumber: 48, title: 'Gudang Bukti Kebanjiran', paragraphs: ['Air pasang memasuki gudang bukti setelah pintu salurannya ditutup petugas. Sari dan Uweng mendengar buku-buku jatuh dari rak, tetapi penjaga menolak membuka pintu tanpa perintah Damar. Mereka memecahkan kisi udara. Uweng masuk sendiri karena tubuh Sari tak muat, mempertaruhkan kebebasan sementaranya.'] },
      { chapterNumber: 49, title: 'Lembar Basah Diselamatkan', paragraphs: ['Uweng keluar membawa buku basah tepat ketika penjaga tiba. Ia ditahan karena merusak gudang, namun Sari mengeringkan lembar angka di atas tungku Ratih. Kapal pemeriksa yang dijadwalkan tiba petang memasuki teluk ketika penjaga menara menyalakan lampu tanda bahaya. Sari menyerahkan halaman sebelum tinta luntur seluruhnya.'] },
      { chapterNumber: 50, title: 'Bak Tua Dipasang', paragraphs: ['Pemeriksa menyegel alat kantor dan memasang kembali bak tua sebagai pembanding. Tuduhan pemalsuan Uweng ditangguhkan, bukan dicabut; ia masih tidur di ruang tahanan. Keluarganya menempati sudut gudang, sementara Bu Hasnah menagih hasil timbang pertama untuk membayar bagian rumah yang sempat dibeli kembali.'] },
    ], justification: 'Bab 33–50 moves from a cracked calibration stone to invalidated certificates, wet salt losses, a pledged and auctioned home, a replacement office scale, and criminal accusation. Saving the evidence requires Sari to expose her private ledger and Uweng to enter a flooded evidence room while detained.' },
    { chapters: [
      { chapterNumber: 33, title: 'Minyak Suar Dijatah', paragraphs: ['Kantor izin mengurangi jatah minyak suar menjadi setengah drum tanpa mengubah jadwal nyala. Penjaga menara meminta Sari mencatat kekurangan itu pada buku pengiriman. Petugas menolak tanda terima dan menyuruh mereka memakai persediaan lama, yang hanya cukup untuk empat malam berangin.'] },
      { chapterNumber: 34, title: 'Sumbu Dipotong Pendek', paragraphs: ['Penjaga memotong sumbu lebih pendek agar minyak bertahan, membuat cahaya hanya menjangkau sisi dalam teluk. Sebuah perahu ikan nyaris menabrak tonggak karang. Nakhodanya menuntut lampu penuh sebelum perjalanan besok. Sari membawa buku jatah ke loket, tetapi Damar meminta halaman musim lalu lebih dahulu.'] },
      { chapterNumber: 35, title: 'Halaman Lama Diminta', paragraphs: ['Halaman musim lalu mencatat tiga malam padam ketika kapal berisi awak tanpa nama masuk. Sari menolak menyerahkannya. Damar menahan drum cadangan sampai buku diperiksa. Penjaga menara membakar minyak dapurnya sendiri, sementara istrinya memasak dengan kayu basah dan menjual cincin untuk membeli persediaan berikutnya.'] },
      { chapterNumber: 36, title: 'Kapal Menabrak Pelampung', paragraphs: ['Cahaya mengecil saat hujan, lalu kapal garam menghantam pelampung batas dan merobek layarnya. Pemilik kapal menagih kerusakan kepada penjaga suar. Damar menawarkan membatalkan tagihan bila buku lama diserahkan sebelum tengah malam. Sari menyalin halaman penting sambil penjaga menghitung sisa minyak untuk satu penyalaan.'] },
      { chapterNumber: 37, title: 'Drum Cadangan Digembok', paragraphs: ['Sari menemukan drum cadangan penuh di gudang kantor, terkunci dengan rantai biru. Ia membawa dua buruh sebagai saksi, tetapi penjaga gudang mengusir mereka dan mencatat nama keduanya. Malam berikut, kedua buruh dilarang bekerja. Keluarga mereka mendatangi menara meminta Sari mengembalikan upah yang hilang.'] },
      { chapterNumber: 38, title: 'Lampu Padam Sebentar', paragraphs: ['Api suar padam selama tujuh menit ketika angin memukul kaca. Dari laut terdengar lonceng kapal mengubah arah. Damar datang membawa surat penutupan menara bila padam terulang. Penjaga menyerahkan kunci ruang minyak kepada Sari, lalu pergi mencari pinjaman untuk membayar awak yang kehilangan kerja.'] },
      { chapterNumber: 39, title: 'Kaca Menara Disita', paragraphs: ['Petugas melepas satu panel kaca dengan alasan pengukuran keselamatan, membiarkan angin menerpa sumbu. Penggantinya baru diberikan setelah buku musim lalu tiba di kantor. Sari menutup celah memakai nampan timah. Panas membengkokkan nampan dan membakar kedua tangannya sebelum malam panjang berakhir.'] },
      { chapterNumber: 40, title: 'Menara Ditutup Siang', paragraphs: ['Surat penutupan ditempel meski lampu bertahan menyala. Penjaga dilarang naik mulai siang, sehingga Sari menyelinap membawa sebotol minyak sebelum tangga dirantai. Kapal malam mengirim isyarat meminta panduan. Jika lampu mati, kantor akan menyalahkan orang terakhir yang tercatat masuk. Lonceng kapal terus berbunyi dari teluk.'] },
      { chapterNumber: 41, title: 'Buku Suar Disita', paragraphs: ['Buku catatan minyak lampu suar disita untuk keperluan pemeriksaan dalam, dan penjaga menara hanya diberi lembaran kosong pengganti. Sari sempat menyalin dua halaman sebelum petugas datang. Menara masih menyala setiap malam. Namun tanggal padamnya lampu pada musim lalu kini hanya tersimpan pada salinan tangan yang mudah dibantah.'] },
      { chapterNumber: 42, title: 'Salinan Tangan Dilarang', paragraphs: ['Pengumuman baru menyatakan hanya buku berjilid kantor yang diterima sebagai catatan pelayaran. Sari menunjukkan salinannya kepada tiga nakhoda; dua menolak membubuhkan tanda tangan karena izin mereka akan diperpanjang pekan ini. Nakhoda ketiga bersedia setelah kapal anaknya tiba, tetapi kapal itu belum tampak.'] },
      { chapterNumber: 43, title: 'Penjaga Suar Dipindah', paragraphs: ['Penjaga menara dipindahtugaskan ke kantor pedalaman, dan penggantinya tidak pernah melihat musim padam itu. Sari menunda menemui penjaga lama karena sibuk mengurus berkas, lalu orang tersebut berangkat sebelum sempat memberi keterangan tertulis. Satu-satunya mulut yang mengingat malam gelap itu kini berada delapan jam perjalanan dari dermaga.'] },
      { chapterNumber: 44, title: 'Surat Bertanggal Kemarin', paragraphs: ['Sari mengejar kereta penjaga dan menemukan surat pindah bertanggal sehari sebelum penyitaan buku. Kusir menolak membawa penumpang tambahan tanpa izin loket. Ia menjual gelangnya untuk menyewa kuda, namun hujan memutus jalan pesisir. Penjaga akan naik kapal pedalaman saat fajar. Jejak roda segera larut dalam lumpur.'] },
      { chapterNumber: 45, title: 'Kapal Pedalaman Berangkat', paragraphs: ['Sari tiba ketika kapal sudah melepaskan tali. Penjaga melemparkan kunci laci menara ke dermaga, lalu berteriak bahwa buku asli disimpan di rak bawah. Petugas mengambil kunci lebih dahulu. Damar menjadwalkan pengosongan menara tiga hari lagi dan melarang siapa pun memasuki ruang arsip.'] },
      { chapterNumber: 46, title: 'Menara Akan Dirobohkan', paragraphs: ['Pengumuman perobohan menara ditempel di kaki tangga, dengan pelaksanaan akhir pekan ini agar lahan dipakai kantor izin. Rak arsip di dalamnya akan ikut dibuang. Sari harus masuk malam ini juga tanpa surat, atau menerima bahwa dasar tanggal yang menopang seluruh catatannya lenyap bersama dinding menara.'] },
      { chapterNumber: 47, title: 'Palu Tiba Lebih Awal', paragraphs: ['Gerobak palu dan linggis datang sehari sebelum jadwal. Pekerja mulai membongkar pagar luar saat Sari memanjat sisi tebing. Ia mencapai jendela arsip, tetapi rak bawah sudah dipindahkan ke halaman kantor. Damar memerintahkan perobohan tangga dahulu agar ia terjebak di atas.'] },
      { chapterNumber: 48, title: 'Tali Turun Diputus', paragraphs: ['Latif melempar tali dari perahu ke jendela menara. Petugas memotong ujung bawah, membuat Sari bergantung di dinding saat batu pertama runtuh. Ia menjatuhkan laci kosong sebagai pengalih, lalu meluncur ke atap gudang. Rak arsip akan dibakar bersama kayu bongkaran sebelum matahari terbit.'] },
      { chapterNumber: 49, title: 'Rak Bawah Dibakar', paragraphs: ['Api menyala di halaman kantor ketika Sari dan Latif tiba melalui saluran pasang. Mereka menarik satu bundel dari rak, tetapi halaman lain menghitam. Damar mengunci gerbang dan memanggil penjaga dari gardu. Sari memilih membawa buku pelayaran, meninggalkan daftar minyak yang terlalu dekat dengan kobaran.'] },
      { chapterNumber: 50, title: 'Tanggal Gelap Terbaca', paragraphs: ['Di hadapan nakhoda, Sari membuka buku pelayaran yang tepinya hangus. Tiga kapal tercatat masuk pada malam suar padam tanpa nama awak. Pemilik kapal yang dulu menabrak pelampung menandatangani salinan. Menara sudah tinggal pondasi, dan penjaga lama belum dapat dipanggil pulang dari pedalaman.'] },
    ], justification: 'Bab 33–50 couples reduced lamp oil with collision liability, worker retaliation, closure, seizure of logs, relocation of the sole witness, and early demolition. Sari must enter the tower under guard and rescue one burning ledger while other records and the tower are lost.' },
  ],
  WEAK: [
    { chapters: [
      { chapterNumber: 33, title: 'Bayang Loket Panjang', paragraphs: ['Damar berhenti di samping meja catat ketika Sari merapikan manifest. Ia menyuruh Sari menjaga tulisan tangannya dan tidak mudah percaya kepada orang yang bertanya. Sebelum Sari sempat meminta penjelasan, Damar melangkah ke loket. Sari menajamkan pena, lalu mencatat peti ikan asin yang baru diturunkan buruh.'] },
      { chapterNumber: 34, title: 'Batuk Dekat Jendela', paragraphs: ['Saat Sari membawa daftar timbang, Damar menahannya dekat jendela. ‘Jangan meninggalkan buku terbuka,’ katanya sambil menunjuk halaman kosong. Ia tidak meminta buku itu. Sari menutup sampul sebelum berjalan ke bak Uweng, kemudian membukanya lagi untuk menyalin angka sambil Damar berbicara dengan penjaga di seberang halaman.'] },
      { chapterNumber: 35, title: 'Tatapan Saat Menimbang', paragraphs: ['Damar mendekati Sari seusai penimbangan dan berkata suara di dermaga mudah berpindah dari satu mulut ke mulut lain. Sari bertanya siapa yang membicarakannya. Damar merapikan manset, menyebut itu nasihat umum, lalu pergi membeli kopi. Sari membawa lembar berat kepada nakhoda dan menerima tanda tangannya.'] },
      { chapterNumber: 36, title: 'Langkah Lewat Gudang', paragraphs: ['Di gerbang gudang, Damar meminta Sari lebih berhati-hati memilih teman bicara. Bu Hasnah yang berdiri di dekatnya mengira teguran itu tentang buruh baru dan menanyakan namanya. Damar tidak menjawab. Mereka masuk membawa dua buku sewa, lalu menghabiskan siang mencocokkan nomor karung dengan manifest kapal utara.'] },
      { chapterNumber: 37, title: 'Bisik Penjaga Pagi', paragraphs: ['Damar menyusul Sari sampai tangga loket dan mengingatkan bahwa juru catat sebaiknya tahu kapan harus diam. Sari memegang map lebih erat, lalu bertanya apakah ada angka yang keliru. Damar menggeleng dan menerima kopi dari Ratih. Kepala loket mencap map Sari sebelum menyerahkannya kembali.'] },
      { chapterNumber: 38, title: 'Topi Biru Melintas', paragraphs: ['Ketika Sari mengambil tinta, Damar melintas di antara peti dan berucap, ‘Jaga apa yang kau tulis.’ Ia terus menuju gudang tali tanpa menoleh. Latif melambaikan tangan dari feri pagi, Uweng memanggil angka berat, dan Ratih mengantar kopi. Sari kembali sebelum tinta pada halaman sebelumnya mengering.'] },
      { chapterNumber: 39, title: 'Diam di Papan Sandar', paragraphs: ['Damar menemukan Sari membaca papan sandar dan menyuruhnya tidak terlalu ingin tahu. Sari menunjukkan bahwa ia hanya menyalin jam keberangkatan Latif. Damar membaca baris yang sama, kemudian pergi menuju loket. Sari memasukkan jadwal ke tas dan membantu Bu Hasnah menghitung peti yang menunggu derek.'] },
      { chapterNumber: 40, title: 'Pesan Tanpa Isi', paragraphs: ['Seorang anak loket menyampaikan ucapan Damar agar Sari ingat batas pekerjaannya. Sari memintanya mengulang, dan anak itu menyebut kalimat yang persis sama sebelum berlari mengejar layang-layang putus. Menjelang sore, Damar terlihat menutup jendela kantor. Sari menyerahkan manifest terakhir kepada kepala loket dan membawa salinannya pulang.'] },
      { chapterNumber: 41, title: 'Peringatan Depan Loket', paragraphs: ['Regent Damar berdiri di depan loket dan berkata pelan bahwa juru catat sebaiknya berhati-hati. Sari mengangguk lalu meneruskan pekerjaannya. Tidak ada surat, tidak ada perubahan jadwal, dan derek tetap berjalan seperti hari sebelumnya. Rasa tidak enak menempel sepanjang siang, tetapi berkas garam sore itu disahkan seperti biasa.'] },
      { chapterNumber: 42, title: 'Kopi Seusai Peringatan', paragraphs: ['Sari mengulang nasihat Damar di warung Ratih sambil merobek pisang rebus. Ratih menirukan nada pelannya hingga dua buruh tertawa. Ketika Sari bertanya apakah Ratih pernah mendengar kalimat serupa, perempuan itu menyebut tiga pedagang yang juga pernah dinasihati. Ceret berikutnya mendidih sebelum loket menutup.'] },
      { chapterNumber: 43, title: 'Peringatan Depan Gudang', paragraphs: ['Regent Damar mengulang kalimat serupa di depan pintu gudang, kali ini sambil menepuk daun pintu. Sari mengangguk lagi dan menyimpan pena. Jadwal timbang tidak berubah, sewa tidak naik, dan tidak seorang pun kehilangan giliran kerja. Kalimat tersebut tetap tinggal sebagai suara tanpa kertas yang menyusulnya.'] },
      { chapterNumber: 44, title: 'Ombak Menyentuh Tiang', paragraphs: ['Di ujung pemecah ombak, Sari menceritakan peringatan kedua kepada Latif. Adiknya mengencangkan simpul layar sambil menyuruhnya menanyakan maksud Damar lain kali. Feri kemudian menerima penumpang terakhir. Sari memegang tali hingga kapal menjauh, lalu pulang bersama Ratih yang membawa keranjang cangkir kotor.'] },
      { chapterNumber: 45, title: 'Jas Putih di Kejauhan', paragraphs: ['Damar berdiri di ujung dermaga ketika muatan ikan asin dinaikkan. Sari menunggu sambil membawa manifest, mengira ia akan mengulang nasihatnya. Damar malah memanggil nakhoda untuk membahas pasang malam. Bu Hasnah menerima berkas dari Sari, membayar buruh, dan menyuruhnya memeriksa hitungan gudang sebelum pulang.'] },
      { chapterNumber: 46, title: 'Peringatan Depan Kapal', paragraphs: ['Untuk ketiga kalinya kalimat berhati-hati itu diucapkan, sekarang di dekat tangga kapal yang sedang dimuat. Sari menjawab seperlunya dan pergi menimbang peti ikan asin. Pekerjaannya utuh, adiknya tetap melaut, warung tetap buka. Ancaman tinggal di ketinggian yang sama sejak awal, tanpa pernah menyentuh satu pun urusan sehari-hari.'] },
      { chapterNumber: 47, title: 'Pena Kembali Menari', paragraphs: ['Sari memakai pena lama untuk mencatat tiga kapal pagi. Damar datang mengambil kopi dan kembali menyuruhnya menjaga pekerjaan baik-baik. Sari kali ini bertanya apakah ia dituduh melakukan kesalahan. Damar berkata tidak, mengambil cangkirnya, lalu duduk di tangga loket sementara Sari menyelesaikan kolom pemilik muatan.'] },
      { chapterNumber: 48, title: 'Sore Tanpa Surat', paragraphs: ['Sebelum makan malam, Sari menceritakan semua ucapan Damar kepada Bu Hasnah. Perempuan itu meminta kalimat persisnya, lalu menyusun potongan ikan ke mangkuk sambil menimbang kemungkinan bahwa Damar sekadar gemar membuat orang gelisah. Latif pulang membawa upah dan bertanya mengapa mereka belum menyentuh nasi.'] },
      { chapterNumber: 49, title: 'Loket Tutup Biasa', paragraphs: ['Saat lonceng petang berbunyi, Damar berdiri di jendela loket dan kembali berkata Sari harus berhati-hati. Sari meletakkan salinan di meja dan memintanya menunjukkan bagian yang salah. Ia menggeser berkas itu kembali tanpa membuka sampul. Kepala loket mengucapkan selamat pulang sambil memasang palang jendela.'] },
      { chapterNumber: 50, title: 'Hari Kerja Berulang', paragraphs: ['Pada akhir pekan, Sari menutup buku sore lalu menerima kunci gudang dari Bu Hasnah. Di jalan keluar, Damar mengangkat telunjuk dan mengulangi nasihat yang sama. Sari menjawab bahwa ia sudah mendengarnya. Ia membawa kunci melewati bak Uweng, sementara Latif menunggu di gerbang dengan ikan untuk makan malam.'] },
    ], justification: 'Across Bab 33–50, looks, footsteps, rumours, and three identical verbal cautions unsettle Sari, but manifests remain approved, routes remain open, wages remain intact, and nobody receives a demand, deadline, or penalty.' },
    { chapters: [
      { chapterNumber: 33, title: 'Desas-desus dari Kapal', paragraphs: ['Awak kapal selatan mengatakan petugas pusat terlihat di pelabuhan lain. Sari bertanya nama kapalnya, tetapi orang itu lupa. Bu Hasnah tetap menyuruh buruh menumpuk garam menurut pesanan. Loket memberi cap tanpa komentar, dan kabar tadi larut dalam percakapan tentang harga ikan.'] },
      { chapterNumber: 34, title: 'Cerita di Warung Garam', paragraphs: ['Di warung, dua nelayan memperdebatkan apakah rombongan pemeriksa sudah berangkat. Yang satu menyebut kereta, yang lainnya menyebut kapal cepat. Sari mendengarkan sambil makan pisang rebus. Tak ada surat pada papan dermaga, sehingga ia kembali bekerja tanpa memindahkan satu berkas pun. Ceret mendesis di antara suara mereka.'] },
      { chapterNumber: 35, title: 'Perahu Asing Melintas', paragraphs: ['Sebuah perahu bercat putih melintas di luar teluk dan memancing dugaan baru. Latif mengenali lambungnya sebagai perahu penjual es, bukan milik kantor pusat. Sari tertawa pendek, lalu melanjutkan hitungan karcis. Jadwal feri serta pembongkaran tetap berjalan tanpa pemeriksaan. Buihnya menghilang dekat pemecah ombak.'] },
      { chapterNumber: 36, title: 'Tanggal Tak Disepakati', paragraphs: ['Pak Uweng mendengar pemeriksa datang hari Kamis, sedangkan Nyi Ratih yakin bulan depan. Mereka bertaruh secangkir kopi, namun keduanya berbicara tanpa sumber tertulis. Sari melihat kalender loket yang kosong. Ia mengarsipkan manifest seperti biasa dan pulang sebelum hujan turun. Lembar Kamis tetap putih tanpa tanda.'] },
      { chapterNumber: 37, title: 'Bendera Bukan Isyarat', paragraphs: ['Bendera kuning dinaikkan pada kapal dagang, membuat buruh mengira rombongan pusat sudah dekat. Nakhoda menjelaskan bendera itu menandakan cat baru belum kering. Orang-orang kembali mengangkat karung. Sari tidak diminta menyiapkan salinan atau menghadiri pertemuan apa pun. Kain kuning berkibar sampai petang.'] },
      { chapterNumber: 38, title: 'Utusan Membawa Ikan', paragraphs: ['Seorang penunggang kuda memasuki halaman kantor dan disebut-sebut sebagai utusan pemeriksa. Ia ternyata mengantar ikan bandeng untuk jamuan Damar. Sari menunggu di bawah talang hingga orang itu keluar membawa keranjang kosong. Tidak ada pengumuman dibacakan kepada pekerja dermaga. Bau bandeng tertinggal dekat tangga kantor.'] },
      { chapterNumber: 39, title: 'Kapal Cepat Tak Tampak', paragraphs: ['Latif mengamati cakrawala dari feri dan tidak melihat kapal cepat yang ramai dibicarakan. Sari memeriksa papan kedatangan; hanya kapal garam serta perahu ikan terdaftar. Mereka membahas cuaca pasang, lalu berpisah menuju pekerjaan masing-masing tanpa menyiapkan jawaban khusus. Cakrawala tetap berisi layar nelayan kecil.'] },
      { chapterNumber: 40, title: 'Bisik Menjelang Senja', paragraphs: ['Bisik-bisik pemeriksaan muncul lagi saat matahari turun. Kali ini seseorang mengaku mendengar lonceng dari kapal pusat, padahal lampu suar mencatat laut sepi. Sari menutup buku muatan dan menyerahkannya kepada Bu Hasnah. Tidak ada orang meminta melihat isinya. Malam tiba tanpa suara jangkar asing.'] },
      { chapterNumber: 41, title: 'Kabar Pemeriksa Datang', paragraphs: ['Kabar beredar di dermaga bahwa pemeriksa dari pusat akan datang memeriksa berkas muatan. Sari mendengarnya dari kuli angkut sambil menunggu derek. Tidak ada tanggal, tidak ada nama, dan tidak ada surat pemberitahuan di papan. Semua orang bekerja seperti biasa sampai matahari condong ke barat.'] },
      { chapterNumber: 42, title: 'Meja Arsip Tetap Sepi', paragraphs: ['Sari membersihkan meja arsip karena mengira tamu mungkin muncul. Debu terkumpul di kain, tetapi pintu kantor tidak terbuka. Bu Hasnah mengirim karung terakhir ke kapal tepat waktu. Menjelang malam, meja itu kembali dipakai untuk menghitung upah seperti setiap akhir hari.'] },
      { chapterNumber: 43, title: 'Kabar Beredar Lagi', paragraphs: ['Kabar yang sama muncul kembali dari mulut awak feri, dengan tambahan bahwa pemeriksa itu galak. Sari menanyakan tanggalnya, dan tidak seorang pun tahu. Berkas tetap disahkan dengan cara lama, timbangan tetap dipegang Pak Uweng, dan loket izin tidak menambah satu pun syarat baru.'] },
      { chapterNumber: 44, title: 'Surat Kosong Tertiup', paragraphs: ['Selembar kertas tertiup dari kantor dan membuat tiga buruh mengejarnya. Kertas itu hanya daftar belanja minyak lampu. Sari mengembalikannya kepada penjaga, yang tidak menyampaikan kabar lain. Ia lalu mencatat muatan sore tanpa perlu memperlihatkan arsip lama. Daftar minyak kembali masuk laci.'] },
      { chapterNumber: 45, title: 'Damar Makan Siang', paragraphs: ['Damar makan siang di warung Ratih ketika orang-orang masih membahas pemeriksa. Ia memesan kopi, membayar, dan kembali ke loket. Sari menunggu kemungkinan perintah sesudahnya. Tak ada panggilan datang; Pak Uweng menyelesaikan timbangannya sebelum air pasang. Piring kotornya segera diangkat Ratih ke meja.'] },
      { chapterNumber: 46, title: 'Kabar Belum Berubah', paragraphs: ['Menjelang pekan pasang kabar itu masih beredar dengan isi yang sama persis. Sari sudah berhenti menanyakannya. Tidak ada kapal tertahan, tidak ada gudang diperiksa, tidak ada orang dipanggil menghadap. Ancaman pemeriksaan hidup hanya sebagai obrolan, dan menunda maupun bergegas sama sekali tidak membedakan hasilnya.'] },
      { chapterNumber: 47, title: 'Teropong Mengarah Laut', paragraphs: ['Penjaga suar meminjamkan teropong kepada Sari untuk mencari kapal pusat. Yang tampak hanya layar nelayan dan burung camar. Ia mengembalikan teropong, lalu turun sebelum gelap. Semua buku yang ditinggalkan di gudang masih berada pada rak semula. Kaca teropong berembun oleh napasnya.'] },
      { chapterNumber: 48, title: 'Kursi Tamu Berdebu', paragraphs: ['Kursi untuk tamu kantor berdebu setelah berhari-hari kosong. Anak loket mengusap dudukannya, kemudian memakai kursi itu untuk tidur siang. Sari lewat membawa manifest yang sudah bercap. Tidak seorang pun menghentikannya ataupun menyebut jadwal kunjungan. Debu baru turun sebelum sore.'] },
      { chapterNumber: 49, title: 'Taruhan Kopi Dibayar', paragraphs: ['Kamis berlalu, sehingga Pak Uweng membayar taruhan kopi kepada Ratih. Mereka masih berbeda pendapat soal bulan depan. Sari ikut tertawa sambil menghitung peti. Kapal berangkat sesuai daftar dan tidak membawa pemeriksa, panggilan, maupun surat bagi mereka. Uap ceret menutupi senyum lebar Uweng.'] },
      { chapterNumber: 50, title: 'Rumor Larut Bersama Pasang', paragraphs: ['Pekan pasang berakhir tanpa rombongan pusat. Kuli yang pertama menyebarkan kabar sudah lupa siapa sumbernya. Sari menyusun buku muatan pada lemari, sedangkan Bu Hasnah mengunci gudang. Bu Hasnah meninggalkan kunci di paku dekat pintu agar Sari dapat membuka gudang saat fajar. Kuli pertama sudah menunggu gerobak di jalan batu.'] },
    ], justification: 'Bab 33–50 repeatedly circulates incompatible rumours about an inspection through boats, flags, riders, and dock gossip. No notice, date, visitor, requirement, held ship, searched warehouse, summons, or material loss ever follows.' },
    { chapters: [
      { chapterNumber: 33, title: 'Daftar Awak Dibaca', paragraphs: ['Kepala sandar membaca daftar awak dengan suara keras sebelum feri berangkat. Nama Latif terdengar di antara belasan nama lain. Sari menoleh dari meja catat, tetapi apel selesai tanpa pesan khusus. Adiknya menerima karcis, mengikat tali, dan berangkat pada giliran pagi.'] },
      { chapterNumber: 34, title: 'Kapur Menggaris Nama', paragraphs: ['Garis kapur terlihat di samping nama Latif pada papan awak. Hujan semalam juga meninggalkan garis serupa pada nama lain. Ia menghapusnya dengan lengan dan menunggu teguran, tetapi kepala sandar hanya meminta semua orang menaikkan peti lebih cepat. Upah dibagikan penuh.'] },
      { chapterNumber: 35, title: 'Petugas Bertanya Ejaan', paragraphs: ['Petugas muda menanyakan apakah nama Latif berakhir dengan huruf f atau p. Sari menjawab, lalu petugas memperbaiki daftar salinan. Tidak ada pertanyaan tentang pekerjaan atau keluarganya. Latif kembali dari penyeberangan membawa ikan pemberian penumpang dan menaruh karcis utuh di meja rumah. Koreksi kecil itu mengering menjelang siang.'] },
      { chapterNumber: 36, title: 'Panggilan Ternyata Lain', paragraphs: ['Teriakan “Latif” terdengar dari dekat loket, membuat Sari meninggalkan hitungan. Seorang penjual tali rupanya memanggil pembeli dengan nama sama. Latif sendiri sedang mengikat feri di ujung dermaga. Jadwalnya tidak bergeser dan kepala sandar tidak mencarinya sepanjang hari. Suara penjual lenyap dalam kerumunan buruh.'] },
      { chapterNumber: 37, title: 'Nama di Kertas Bekas', paragraphs: ['Sari menemukan nama adiknya pada kertas pembungkus ikan. Kertas itu potongan daftar awak bulan lalu yang dibuang kantor. Baris Latif tidak memiliki tanda atau catatan tambahan. Ratih memakai sisanya untuk membungkus pesanan, sementara Sari kembali mengisi kolom muatan. Bungkus itu segera ternoda minyak ikan.'] },
      { chapterNumber: 38, title: 'Apel Berjalan Singkat', paragraphs: ['Apel pagi berlangsung singkat karena hujan. Nama Latif tetap dibaca, lalu semua awak berlari ke kapal masing-masing. Tak ada orang ditahan setelah barisan bubar. Sari melihat feri adiknya meninggalkan tambatan tepat ketika lonceng pertama berbunyi. Hujan memukul papan yang ditinggalkan.'] },
      { chapterNumber: 39, title: 'Bisik Soal Daftar', paragraphs: ['Seorang buruh berkata daftar awak sedang diperiksa kantor izin. Ketika Sari meminta bukti, ia menunjuk papan biasa yang tidak berubah. Latif mengangkat bahu dan mengambil bekalnya. Sepanjang dua trayek hari itu, tidak ada pemeriksaan karcis ataupun pengurangan tugas. Bekalnya habis sebelum feri kembali.'] },
      { chapterNumber: 40, title: 'Pena Berhenti Sesaat', paragraphs: ['Kepala sandar berhenti sesaat sebelum membaca nama Latif, sebab tintanya menetes pada halaman. Ia mengusap noda lalu melanjutkan apel. Sari sempat mencemaskan jeda tersebut. Sesudahnya adiknya menerima tali sandar yang sama dan pulang dengan jumlah upah lazim. Noda tinta tersisa dekat huruf namanya.'] },
      { chapterNumber: 41, title: 'Nama Latif Disebut', paragraphs: ['Seorang petugas menyebut nama Latif ketika membaca daftar awak di papan sandar. Sari mendengarnya dari jarak beberapa langkah dan berhenti menulis sejenak. Petugas melanjutkan membaca nama lain lalu menutup daftar. Adiknya tetap berangkat pada trayek pagi seperti bulan sebelumnya, membawa bekal yang sama.'] },
      { chapterNumber: 42, title: 'Bekal Pulang Utuh', paragraphs: ['Latif pulang membawa kotak bekal kosong dan dua karcis yang sudah dilubangi. Ia berkata tak ada kejadian di kapal selain anak kecil mabuk laut. Sari memeriksa papan dari kejauhan. Nama adiknya masih tercetak pada dua giliran untuk esok. Tas kerja digantung dekat tikar rumah.'] },
      { chapterNumber: 43, title: 'Nama Disebut Ulang', paragraphs: ['Nama tersebut disebut lagi pada apel dermaga, tanpa penjelasan mengapa. Sari menunggu kelanjutannya sampai apel bubar. Tidak ada panggilan menghadap, tidak ada surat, dan jadwal feri tertempel utuh di papan. Latif sendiri bahkan tidak menganggap penyebutan itu penting ketika ditanya malam harinya.'] },
      { chapterNumber: 44, title: 'Feri Kembali Tepat', paragraphs: ['Feri kembali sebelum pasang menutup undakan. Latif turun bersama penumpang dan menyerahkan catatan bahan bakar tanpa masalah. Kepala sandar memeriksa tali, lalu mengangguk. Sari tidak melihat petugas loket mendekati adiknya atau menaruh surat pada tas kerjanya. Air pasang berkilat di bawah lunas.'] },
      { chapterNumber: 45, title: 'Papan Dijemur Matahari', paragraphs: ['Papan awak diturunkan untuk dijemur setelah terkena hujan. Semua nama tampak lebih jelas, termasuk milik Latif pada trayek pagi. Sari membantu memegang sudutnya. Petugas mengucapkan terima kasih, memasang papan kembali, dan tidak mengubah satu baris pun. Kayunya kering sebelum apel berikut.'] },
      { chapterNumber: 46, title: 'Nama Tetap Disebut', paragraphs: ['Pada apel berikutnya nama itu kembali terbaca dengan nada yang sama. Sari tidak lagi berhenti menulis. Trayek pagi masih miliknya, upah tidak dipotong, dan tali sandar tetap dipegang orang yang sama. Penyebutan berulang tersebut tidak pernah menjadi tindakan yang mengubah apa pun bagi keluarga mereka.'] },
      { chapterNumber: 47, title: 'Karcis Baru Dicetak', paragraphs: ['Kantor mencetak karcis feri baru dengan warna hijau. Latif menerima satu ikat sesuai jatah dan menaruhnya dalam tas. Namanya ditulis petugas tanpa komentar. Sari melihat proses itu sambil menunggu tinta manifest kering, lalu mereka berangkat ke pekerjaan masing-masing. Tinta hijau menempel pada jarinya.'] },
      { chapterNumber: 48, title: 'Tali Lama Digulung', paragraphs: ['Latif menggulung tali sandar lama karena seratnya mulai mengembang. Kepala sandar memberinya tali pengganti dari gudang alat. Tidak ada biaya dibebankan dan tidak ada catatan dibuat atas namanya. Ia menyelesaikan giliran kedua sebelum makan malam, lalu mengikat tali baru pada gulungan lama di tepi gudang.'] },
      { chapterNumber: 49, title: 'Upah Masuk Kaleng', paragraphs: ['Upah Latif berdenting saat dimasukkan ke kaleng rumah. Jumlahnya sama dengan pekan lalu. Sari membagi keping untuk beras dan minyak, lalu memasukkan sisanya kembali ke kaleng rumah. Daftar awak tidak dibicarakan lagi malam itu. Tutup kaleng dipasang rapat oleh Sari.'] },
      { chapterNumber: 50, title: 'Apel Terakhir Tenang', paragraphs: ['Pada apel akhir pekan, nama seluruh awak dibaca menurut urutan abjad. Latif menjawab hadir dan naik feri. Sari melanjutkan tulisan sebelum kapal meninggalkan dermaga. Kepala sandar menutup daftar, menyimpannya di laci, lalu pergi sarapan tanpa memanggil siapa pun. Feri mengecil jauh di ujung teluk.'] },
    ], justification: 'Bab 33–50 makes Latif’s name conspicuous through roll calls, chalk, scraps, and questions about spelling, but he keeps every route, ticket, tool, and full wage. No summons, sanction, deadline, or imposed choice appears.' },
    { chapters: [
      { chapterNumber: 33, title: 'Keluh di Balik Ceret', paragraphs: ['Ratih menghitung pendapatan pagi dan menemukan jumlah kopi lebih sedikit daripada kemarin. Ia menuduh pekerja loket menghindari warung setelah mendengar rencana kenaikan sewa. Sari menunjuk kapal penumpang yang belum merapat. Menjelang siang, awaknya memenuhi bangku dan Ratih menambah air ke dalam ceret kedua.'] },
      { chapterNumber: 34, title: 'Hitung Uang Receh', paragraphs: ['Nota gula mencantumkan dua baris ongkos angkut. Ratih mengira pedagang menaikkan harga karena warungnya akan digusur. Pedagang membuka buku dan menunjukkan satu baris untuk karung kemarin yang belum dibayar. Ratih mencocokkan jumlah keping, melunasi keduanya, lalu menyimpan nota di bawah kaleng kopi.'] },
      { chapterNumber: 35, title: 'Angin Menggoyang Tagihan', paragraphs: ['Ketika satu keping sewa terselip di bawah meja, Ratih menganggap penagih sengaja meninggalkannya sebagai sindiran. Sari mengenali keping itu sebagai uang kembalian pelanggan. Ratih memasukkannya ke piring kas, lalu mencatat enam cangkir dan dua pisang rebus yang baru dibawa ke meja buruh.'] },
      { chapterNumber: 36, title: 'Bangku Tetap Penuh', paragraphs: ['Tiga bangku kosong saat jam makan membuat Ratih yakin kabar buruk sedang beredar tentang warung. Uweng datang terlambat bersama para buruh yang harus menyelesaikan timbang. Mereka memesan gorengan sampai wajan pertama habis. Ratih menghapus hitungan sepi dari papan kecil dan menuliskan tambahan adonan untuk sore.'] },
      { chapterNumber: 37, title: 'Kaleng Masih Berdenting', paragraphs: ['Ratih menemukan angka miring pada kuitansi bulanan dan membacanya sebagai tarif baru. Sari memutar kertas; tanda itu ternyata ekor cap lunas yang tercetak terbalik. Ratih memeriksanya dekat jendela, lalu melipat kuitansi ke buku warung. Setelah itu ia menghitung uang bahan sambil terus menggerutu tentang tulisan penagih.'] },
      { chapterNumber: 38, title: 'Cerita Penyewa Sebelah', paragraphs: ['Penyewa sebelah bercerita bahwa lapaknya diminta membayar papan tambahan. Ratih langsung menyisihkan keping dari kaleng seolah tagihan serupa akan datang. Sari melihat papan baru yang dipasang penyewa itu sendiri untuk berjualan ikan kering. Ratih mengembalikan keping ke tumpukan gula, minyak, dan sewa bulan depan.'] },
      { chapterNumber: 39, title: 'Kapur Menulis Harga', paragraphs: ['Tulisan kapur harga kopi terhapus sebagian oleh lengan pelanggan. Ratih mengira seseorang sedang menguji berapa cepat ia menaikkan harga sebelum sewa berubah. Pelanggan meminta maaf dan menyalin kembali angka lama. Ratih menerima bayarannya, lalu menggeser papan ke dekat ceret agar tidak tersenggol lagi.'] },
      { chapterNumber: 40, title: 'Penagih Minum Kopi', paragraphs: ['Penagih memesan kopi tanpa gula dan meminta kuitansi disiapkan. Ratih mengira ia datang sehari lebih cepat untuk menambah biaya. Lelaki itu menunjukkan tanggal pada buku dan menjelaskan besok kantor tutup karena perbaikan atap. Ratih membayar jumlah bulan lalu, menerima cap, lalu memberinya pisang rebus sebagai kembalian.'] },
      { chapterNumber: 41, title: 'Ratih Mengeluh Sewa', paragraphs: ['Nyi Ratih mengeluh tentang sewa lapak sambil menyeduh kopi untuk kuli pagi. Sari mendengarkan sambil menghitung peti. Angka sewa di kertas tempel belum berubah sejak musim lalu, dan tidak ada petugas yang datang menagih. Warung tetap penuh sampai tengah hari seperti kebiasaan bertahun-tahun.'] },
      { chapterNumber: 42, title: 'Gula Datang Dua Karung', paragraphs: ['Pedagang mengantar dua karung gula, tetapi Ratih hanya menemukan satu karung pada catatan pesanan. Ia menuduh pemasok memanfaatkan kabar sewa. Anak pengantar membuka lipatan nota yang menempel; baris kedua memang tertulis di baliknya. Ratih tertawa malu, membayar, lalu meminta Sari membantu menaikkan kedua karung ke rak.'] },
      { chapterNumber: 43, title: 'Ratih Mengeluh Cuaca', paragraphs: ['Keluhan berikutnya soal sewa muncul lagi di sela obrolan tentang angin timur. Nyi Ratih menyebut kantor izin serakah lalu tertawa. Kertas tempel di dinding masih memuat angka lama, kaleng uang masih terisi, dan tidak ada surat teguran yang pernah sampai ke tangannya.'] },
      { chapterNumber: 44, title: 'Pipa Mengalir Jernih', paragraphs: ['Air dari pipa mengecil ketika Ratih membilas cangkir. Ia menduga kantor mulai membatasi warungnya dan menyuruh Sari mengisi semua kendi. Uweng kemudian menemukan serabut kelapa tersangkut di mulut keran. Setelah serabut dicabut, Ratih menuangkan kembali dua kendi ke tempayan agar lantai dapur tidak sesak.'] },
      { chapterNumber: 45, title: 'Tirai Baru Dipasang', paragraphs: ['Pengrajin membawa tirai anyaman dan meminta sisa pembayaran. Ratih salah membaca catatan muka sebagai biaya izin pemasangan. Sari menunjukkan tanda tangan Ratih sendiri di samping angka tersebut. Ratih membayar pengrajin, memasang tirai pada jendela laut, lalu mencatat pembelian itu di halaman perabot warung.'] },
      { chapterNumber: 46, title: 'Ratih Mengeluh Kopi', paragraphs: ['Sambil mengaduk kopi, keluhan yang sama diulang untuk kesekian kali. Sari tersenyum tipis dan menuliskan jumlah peti. Sewa belum naik, air masih mengalir, dan bangku panjang tetap berjejer menghadap laut. Tekanan terhadap warung berhenti pada tingkat keluhan, tanpa satu pun langkah yang mempersempit pilihan.'] },
      { chapterNumber: 47, title: 'Kuitansi Bulanan Datang', paragraphs: ['Penagih menyerahkan kuitansi bulan berikutnya. Ratih membacanya keras-keras dan berhenti pada angka yang tampak lebih panjang. Setitik kopi ternyata menempel di belakang digit terakhir. Ia mengusapnya dengan ujung celemek, menghitung keping sesuai tarif lama, lalu meminta Sari menyimpan kuitansi setelah cap mengering.'] },
      { chapterNumber: 48, title: 'Gorengan Habis Cepat', paragraphs: ['Gorengan habis sebelum tengah hari dan piring uang penuh keping kecil. Ratih mengira pelanggan membayar kurang karena mendengar warung akan pindah. Sari menghitung ulang dan menemukan dua keping terselip di bawah daun pisang. Ratih menambah adonan, sementara buruh mengetuk meja meminta pesanan kedua.'] },
      { chapterNumber: 49, title: 'Bangku Menghadap Senja', paragraphs: ['Seorang buruh menawarkan tenda ikan setelah Ratih kembali bercerita tentang kemungkinan penggusuran. Ratih menyangka ia sedang menawar peralatan warung dan mulai menyebut harga bangku. Buruh lain tertawa lalu menjelaskan tenda itu tempat sementara untuk pesta anaknya. Ratih menuangkan kopi kedua dan ikut menertawakan salah paham tersebut.'] },
      { chapterNumber: 50, title: 'Warung Buka Lagi', paragraphs: ['Saat fajar, Ratih membuka buku kas dan mengira halaman kosong berarti seseorang mencabut catatan sewa. Sari menemukan dua halaman yang melekat karena percikan gula. Angka lama muncul setelah dipisahkan. Ratih menaruh pemberat di sudut buku, menyalakan tungku, lalu menyambut buruh pertama yang membawa uang pas.'] },
    ], justification: 'Throughout Bab 33–50, Ratih repeatedly imagines rent hikes or eviction while receipts remain unchanged and paid. Water, suppliers, furniture, equipment, hours, customer traffic, and savings all remain available without an external demand.' },
    { chapters: [
      { chapterNumber: 33, title: 'Dua Buruh Baru', paragraphs: ['Pak Uweng menurunkan suara ketika dua buruh baru menunggu giliran timbang. Ia bertanya kepada Sari siapa yang mengirim mereka dan mengapa keduanya terus melihat bak. Salah satu buruh menjawab mereka menunggu karung milik mandor. Uweng mengangguk, lalu membaca angka berat sambil sesekali memperhatikan antrean.'] },
      { chapterNumber: 34, title: 'Jejak Dekat Bak', paragraphs: ['Seorang nakhoda meminta Uweng mengulang angka karena ombak menelan suaranya. Uweng menganggap permintaan itu sindiran terhadap ketelitiannya dan menjawab lebih keras dari perlu. Sari menunjukkan catatan yang sama kepada nakhoda. Lelaki itu membubuhkan tanda tangan, lalu menyuruh awak memindahkan karung ke geladak.'] },
      { chapterNumber: 35, title: 'Bayang Melintas Cepat', paragraphs: ['Uweng melihat tiga buruh berbisik dekat tiang dan yakin mereka sedang membicarakan baknya. Ia mendekat sambil membawa pemberat. Mereka ternyata menyusun patungan makan siang, tetapi berhenti bicara ketika Uweng datang. Ia kembali ke meja dengan wajah masam dan menimbang karung berikutnya dua kali.'] },
      { chapterNumber: 36, title: 'Suara dari Atap', paragraphs: ['Saat Bu Hasnah meminta bak dibersihkan sebelum muatan baru datang, Uweng bertanya apakah ada pembeli yang mengeluh diam-diam. Bu Hasnah menyerahkan sikat dan mengatakan garam mengerak di sudut. Uweng menggosok bak sendiri, lalu memanggil Sari untuk memastikan garis ukur masih terlihat sebelum karung pertama dinaikkan.'] },
      { chapterNumber: 37, title: 'Kopi Dicicipi Dahulu', paragraphs: ['Ratih mengirim kopi melalui pelayan baru. Uweng menolak meminumnya sebelum Sari mencicipi, sebab ia tidak mengenal pembawanya. Pelayan itu tertawa dan menunjukkan celemek warung yang masih kebesaran. Setelah Sari minum seteguk, Uweng menghabiskan cangkir sambil bertanya sejak kapan Ratih mempekerjakan anak tersebut.'] },
      { chapterNumber: 38, title: 'Pintu Berderit Sendiri', paragraphs: ['Dua pembeli mencocokkan angka pada buku mereka setelah meninggalkan bak. Uweng mengikuti sampai pintu gudang dan meminta tahu selisihnya. Keduanya menunjukkan hitungan pembagian ongkos perahu, bukan berat garam. Ia kembali sambil menggerutu, lalu menyuruh Sari membacakan skala karung selanjutnya dengan suara nyaring.'] },
      { chapterNumber: 39, title: 'Batuk di Lorong', paragraphs: ['Penjaga gudang menyapa Sari tetapi tidak menyebut nama Uweng. Juru timbang itu segera bertanya mengapa dirinya diabaikan. Penjaga mengaku sedang sakit tenggorokan dan mengangkat sapu sebagai salam. Uweng membalas dengan anggukan pendek, kemudian mengatur pemberat sambil mengamati siapa saja yang masuk melalui pintu samping.'] },
      { chapterNumber: 40, title: 'Mata dari Jendela', paragraphs: ['Anak-anak berhenti dekat jendela untuk melihat pemberat naik turun. Uweng menyuruh mereka menghadapnya dan menanyakan siapa yang menyuruh datang. Mereka menyebut guru sekolah yang memberi tugas menggambar pekerjaan dermaga. Sari meminjamkan arang tulis, sedangkan Uweng berkeras berdiri di antara gambar mereka dan sertifikat tera.'] },
      { chapterNumber: 41, title: 'Uweng Merasa Diawasi', paragraphs: ['Pak Uweng berkata ia merasa ada yang mengawasi bak penimbang dari balik tumpukan goni. Sari menoleh dan tidak menemukan siapa pun. Timbangan tetap dipakai sepanjang hari, sertifikat tera menggantung di dinding, dan angka berat masuk ke buku muatan tanpa pertanyaan dari loket.'] },
      { chapterNumber: 42, title: 'Kopi untuk Penenang', paragraphs: ['Sari membawa kopi Ratih ketika Uweng menuduh buruh sengaja berbicara pelan di belakangnya. Ia menunjuk dua orang yang sedang membagi pesanan ikan untuk keluarga. Sari duduk di tepi bak sampai Uweng mau minum. Sesudah cangkir kosong, ia masih meminta setiap angka diulang sebelum ditulis.'] },
      { chapterNumber: 43, title: 'Uweng Merasa Diikuti', paragraphs: ['Kegelisahan yang sama diulang juru timbang itu pada sore berikutnya, kali ini menyebut langkah kaki di lorong gudang. Sari memeriksa lorong dan hanya menemukan kucing dermaga. Alat penimbang belum diganti, izinnya belum dipertanyakan, dan pekerjaan berjalan mengikuti urutan yang sudah lama dihafal.'] },
      { chapterNumber: 44, title: 'Kucing Tidur di Bak', paragraphs: ['Seorang awak tertawa ketika Uweng salah menyebut nomor karung. Uweng menuntut penjelasan di depan seluruh antrean. Awak itu mengaku teringat lelucon Ratih dan meminta maaf, lalu mengangkat karungnya. Sari membetulkan nomor pada halaman, sementara Uweng memeriksa wajah buruh lain sebelum meneruskan pembacaan skala.'] },
      { chapterNumber: 45, title: 'Peluit dari Feri', paragraphs: ['Peluit feri membuat beberapa buruh menoleh dan berbisik tentang jadwal pulang. Uweng mengira mereka memberi isyarat saat punggungnya berbalik. Latif datang dari geladak dan menjelaskan feri terlambat karena penumpang membawa kambing. Uweng menimbang karung berikutnya sambil meminta Sari tetap berdiri di sisi belakang bak.'] },
      { chapterNumber: 46, title: 'Uweng Merasa Sama', paragraphs: ['Perasaan diawasi tersebut disebut lagi menjelang pekan pasang tanpa satu pun bukti baru. Sari sudah terbiasa menjawab dengan anggukan. Bak penimbang tetap miliknya, sertifikat masih berlaku, dan tidak ada surat panggilan yang menyusul. Kecurigaan berputar di tempat yang sama sepanjang tiga kali percakapan.'] },
      { chapterNumber: 47, title: 'Antrean Masih Panjang', paragraphs: ['Bu Hasnah memindahkan dua buruh ke pintu timur agar gerobak tidak bertumpuk. Uweng melihat mereka pergi dan bertanya apakah orang-orang mulai menghindari timbangannya. Sari menunjukkan antrean yang masih memanjang sampai halaman. Ia memanggil nomor berikut, lalu Uweng meminta pemilik karung menyebut namanya sebelum skala dibaca.'] },
      { chapterNumber: 48, title: 'Sertifikat Dibersihkan Debu', paragraphs: ['Sari menurunkan sertifikat tera untuk membersihkan bingkainya. Uweng melihat ruang kosong di dinding dan menuduh seseorang telah mengaduk-aduk alatnya. Sari mengangkat kain berdebu serta menunjukkan kertas di tangannya. Uweng memasang bingkai sendiri, kemudian memeriksa simpul gantungnya tiga kali sebelum kembali menimbang.'] },
      { chapterNumber: 49, title: 'Timbangan Menutup Hari', paragraphs: ['Menjelang senja, Uweng bertanya mengapa Bu Hasnah menghitung upah di ruangan sebelah. Ia khawatir para buruh sedang membandingkan bagiannya. Bu Hasnah memanggilnya masuk dan menyerahkan keping sesuai daftar. Uweng menghitung di depan Sari, menyimpan uang dalam ikat pinggang, lalu kembali untuk menutup bak.'] },
      { chapterNumber: 50, title: 'Pagi Tanpa Pengintai', paragraphs: ['Ketika gudang dibuka, Uweng meminta setiap buruh menyebut nama sebelum mendekati bak. Beberapa orang menggodanya dengan nama palsu sampai Bu Hasnah menyuruh mereka berhenti. Sari menyiapkan buku baru dan memanggil karung pertama. Uweng memeriksa titik nol, menatap antrean sekali lagi, lalu mengangkat tangan sebagai tanda mulai.'] },
    ], justification: 'Bab 33–50 repeats Uweng’s suspicion through shadows, tracks, noises, animals, and ordinary visitors. His scale, certificate, access, workload, accepted figures, and wages remain untouched, with no official intervention or time-bound demand.' },
  ],
  BORDERLINE: [
    { chapters: [
      { chapterNumber: 33, title: 'Map Arsip Dibereskan', paragraphs: ['Kepala loket meminta map arsip disusun menurut warna sebelum akhir bulan. Ketika Sari bertanya tentang map yang salah tempat, ia sudah berjalan menuju loket. Sari mulai dari rak bawah dan menyelesaikan separuhnya. Pekerjaan bongkar-muat tetap berjalan; hanya waktu makan siangnya berkurang karena debu membuat urutan warna sulit dibaca.'] },
      { chapterNumber: 34, title: 'Daftar Warna Ditempel', paragraphs: ['Daftar warna ditempel di pintu kantor beserta tanggal penyelesaian. Sari menyalinnya pada telapak tangan karena kertas cadangan habis. Petugas mengingatkan masih ada dua pekan. Tidak ada denda tertulis, namun Bu Hasnah memberi satu buruh untuk membantu memindahkan map. Tinta di telapak luntur oleh keringat.'] },
      { chapterNumber: 35, title: 'Dua Rak Tertukar', paragraphs: ['Buruh bantuan menaruh map biru pada rak hijau sehingga Sari mengulang penyusunan sore itu. Ia melewatkan feri pulang dan membayar perahu nelayan satu keping. Kepala loket melongok dari pintu, melihat dua rak yang sudah rapi, lalu pergi sebelum Sari sempat memanggilnya.'] },
      { chapterNumber: 36, title: 'Tinta Warna Menipis', paragraphs: ['Tinta penanda tinggal sedikit, sedangkan empat rak belum disentuh. Sari membeli botol kecil memakai uang makan karena kantor tidak menyediakan. Damar lewat dan menunjuk kalender. Damar mengetuk tanggal pada kalender dengan kukunya. ‘Akhir bulan tetap akhir bulan,’ katanya sebelum melanjutkan langkah.'] },
      { chapterNumber: 37, title: 'Malam Pertama Menyusun', paragraphs: ['Sari tinggal setelah lampu suar menyala untuk menyusun map. Penjaga mengizinkannya pulang melalui gerbang samping. Bu Hasnah mengantar nasi dingin, lalu membantu satu jam. Saat mereka pulang, awak malam masih menimbang karung terakhir dan lampu kapal esok sudah tampak di teluk.'] },
      { chapterNumber: 38, title: 'Hitungan Rak Berbeda', paragraphs: ['Catatan loket menyebut sembilan rak, sementara gudang hanya memiliki delapan. Sari meminta penjelasan dan disuruh mengosongkan sebuah peti sebagai rak kesembilan. Ia memindahkan tali temali ke lantai. Hujan membasahi satu gulung tali, yang masih dapat dijemur sebelum dipakai. Tali basah digantung dekat jendela.'] },
      { chapterNumber: 39, title: 'Kalender Dilingkari Merah', paragraphs: ['Seseorang melingkari tanggal akhir bulan dengan tinta merah. Sari menghitung enam hari tersisa dan meminta Latif mengantar makan agar ia tak keluar dari arsip. Ketika Sari bertanya apa yang menyusul setelah tanggal itu, Damar melipat kalender tanpa jawaban. Sari membatalkan kunjungan keluarga akhir pekan.'] },
      { chapterNumber: 40, title: 'Lima Map Belum Urut', paragraphs: ['Lima map masih salah urut ketika tinggal dua hari. Sari membawa sebagian ke meja warung Ratih dan bekerja sambil minum kopi. Petugas melihatnya, menyuruh map dikembalikan sebelum malam, lalu mencatat namanya. Petugas mengembalikan map ke lengannya dan membiarkannya melewati gerbang. Ratih menjaga tumpukan dari cipratan kopi.'] },
      { chapterNumber: 41, title: 'Sebelum Pekan Pasang', paragraphs: ['Regent Damar menyebut seluruh berkas lama harus dirapikan sebelum pekan pasang berakhir. Kalimat itu punya batas waktu, tetapi tidak menyebut apa yang terjadi bila lewat. Sari menghitung sisa hari di kertas bekas. Ia mulai memilah tumpukan berkas lebih awal, meski belum tahu apakah kelalaian akan berbuah denda, teguran, atau tidak apa-apa.'] },
      { chapterNumber: 42, title: 'Jam Makan Dilewatkan', paragraphs: ['Sari melewatkan makan siang demi memeriksa tanggal pada map terakhir. Tangannya gemetar saat menulis, sehingga satu label harus diganti. Bu Hasnah menyisakan nasi di dapur. Menjelang senja, petugas mencap manifest terakhir dan Bu Hasnah menaruh upah Sari di samping nasi dingin.'] },
      { chapterNumber: 43, title: 'Hari Dihitung Mundur', paragraphs: ['Sisa hari menjelang batas tersebut disebut ulang di papan pengumuman dengan angka yang dicoret setiap pagi. Sari merapikan berkas sampai larut sambil menunggu kejelasan akibat. Tidak ada contoh orang yang pernah dihukum karena batas semacam ini. Tekanan waktunya nyata di kepala, sedangkan akibatnya masih menggantung tanpa bentuk.'] },
      { chapterNumber: 44, title: 'Satu Laci Macet', paragraphs: ['Laci terakhir macet karena garam mengerak pada relnya. Pak Uweng membantu mencongkel dengan pisau timbang, menghabiskan satu jam kerja. Dua karung menunggu lebih lama, namun kapalnya masih tertambat. Petugas mencoret angka pada papan tanpa memeriksa isi laci. Kapal baru melepas tali menjelang petang.'] },
      { chapterNumber: 45, title: 'Berkas Tertinggal Tiga', paragraphs: ['Tiga berkas kapal lama ditemukan di bawah peti setelah rak dianggap selesai. Sari membawa semuanya ke loket menjelang tutup. Kepala loket menunjuk tenggat esok pagi dan menolak bekerja lembur. Ia pulang membawa tiga label kosong. Sampai minyak lampu habis, pertanyaannya tentang akibat keterlambatan belum mendapat jawaban.'] },
      { chapterNumber: 46, title: 'Batas Waktu Lewat', paragraphs: ['Batas itu terlewat pada pagi berkabut, dan Sari menunggu di dekat loket dengan berkas belum selesai. Petugas hanya mencatat namanya pada buku kecil lalu menyuruhnya pulang. Tidak ada denda dan tidak ada pemulihan. Waktu telah memaksa langkahnya, tetapi kerugian yang sesungguhnya belum pernah menampakkan wujud.'] },
      { chapterNumber: 47, title: 'Nama Dalam Buku Kecil', paragraphs: ['Sari melihat namanya pada buku kecil bersama tujuh pekerja lain. Petugas menutup halaman ketika ditanya kegunaannya. Ia masih boleh memasuki gudang dan mengesahkan muatan. Dua buruh di antrean membaca namanya sebelum petugas menutup halaman. Sari menunduk dan mempercepat langkah menuju gudang.'] },
      { chapterNumber: 48, title: 'Teguran Lisan Singkat', paragraphs: ['Kepala loket memanggil Sari untuk menanyakan tiga berkas terlambat. Setelah mendengar laci macet, ia memberi teguran lisan dan menyuruhnya lebih teliti. Pertemuan selesai sebelum kopi dingin. Sari keluar membawa kunci arsip dan menemukan upahnya masih terlipat utuh di meja Bu Hasnah. Cangkir itu masih penuh ketika ia keluar.'] },
      { chapterNumber: 49, title: 'Rak Kembali Dipakai', paragraphs: ['Map yang sudah diurutkan kembali dipakai petugas untuk mencari manifest lama. Dua label terkelupas dan Sari diminta menempelkannya lagi saat sempat. Ia menyelesaikan pekerjaan selepas timbang, lalu pulang dengan feri biasa tanpa jam tambahan wajib. Lem label mengering sebelum Sari pergi.'] },
      { chapterNumber: 50, title: 'Catatan Nama Dicoret', paragraphs: ['Petugas mencoret nama Sari dari buku kecil setelah semua berkas ditemukan. Setelah namanya dicoret, Sari kembali ke meja catat dan membuka manifest kapal pagi. Botol tinta yang dibelinya sendiri hampir habis, sedangkan kunjungan keluarga yang dibatalkan tak dapat diulang pekan itu. Bekas coretan tetap terlihat pada kertas.'] },
    ], justification: 'Bab 33–50 gives Sari a visible countdown that consumes meals, sleep, ink money, ferry fare, and a family visit. Missing it produces only a name entry and brief oral reprimand; her pay, access, duties, and warehouse operations remain intact.' },
    { chapters: [
      { chapterNumber: 33, title: 'Kapur Menandai Rak', paragraphs: ['Petugas menggambar tanda kapur pada tiga rak depan tanpa menerangkan maksudnya. Bu Hasnah meminta Sari memindahkan karung paling mahal ke belakang. Mereka bekerja satu jam setelah tutup gudang. Tak ada karung disita, tetapi punggung Bu Hasnah sakit saat mengangkat sudut yang berat.'] },
      { chapterNumber: 34, title: 'Surat Pemeriksaan Terselip', paragraphs: ['Sari menemukan surat pemeriksaan terselip di bawah pintu. Tanggalnya jelas dua pekan lagi, sedangkan bagian mengenai tindakan lanjutan tidak terisi. Ia membacanya kepada buruh. Sebagian ingin memindahkan semua karung; Bu Hasnah memilih menunggu petunjuk agar kerja bongkar tidak terhenti. Debu pintu melekat pada cap surat.'] },
      { chapterNumber: 35, title: 'Karung Belakang Ditumpuk', paragraphs: ['Mereka menumpuk dua puluh karung di rak belakang untuk berjaga-jaga. Lorong menjadi sempit dan satu buruh menjatuhkan kait besi ke kakinya. Luka itu dibalut Ratih, lalu ia pulang lebih awal. Pengganti dibayar setengah hari, meski kantor belum meminta pemindahan tersebut.'] },
      { chapterNumber: 36, title: 'Cap Datang Tanpa Isi', paragraphs: ['Salinan surat baru tiba dengan cap lilin biru, namun kotak sanksi tetap putih. Sari bertanya di loket dan mendapat jawaban bahwa keputusan bergantung pada temuan petugas. Ia membeli kain penutup tambahan. Dua karung gagal dimuat karena waktu habis saat kain diikat.'] },
      { chapterNumber: 37, title: 'Debu Garam Dibersihkan', paragraphs: ['Bu Hasnah menyuruh seluruh lantai disikat sebelum kedatangan petugas. Debu garam membuat tangan para buruh pecah, tetapi mereka menerima upah lembur kecil. Sari mencatat nomor rak sampai malam. Damar lewat, memeriksa cap surat, lalu pergi tanpa menyebut barang yang dilarang.'] },
      { chapterNumber: 38, title: 'Daftar Pertanyaan Kosong', paragraphs: ['Kantor membagikan lembar persiapan berisi ruang kosong untuk pertanyaan pemeriksa. Sari menebak mereka mungkin menanyakan asal garam, lalu menyalin manifest setahun. Bu Hasnah menyewa satu meja tambahan. Bu Hasnah mengambil uang meja dari kaleng gudang. Ketika Sari bertanya barang apa yang dilarang, lembar persiapan di tangannya tetap kosong.'] },
      { chapterNumber: 39, title: 'Tujuh Hari Menunggu', paragraphs: ['Angka tujuh ditulis pada papan hitung mundur. Buruh mulai menghindari rak bertanda kapur karena takut barangnya kelak dianggap salah. Akibatnya, muatan dari rak belakang bergerak lebih lambat. Satu nakhoda mengeluh, tetapi tetap menerima pengiriman pada pasang berikutnya. Gerobak berikutnya tiba mendekati senja.'] },
      { chapterNumber: 40, title: 'Jalur Tengah Dikosongkan', paragraphs: ['Sari mengosongkan jalur tengah untuk memberi ruang kepada rombongan pemeriksa. Peti ikan asin dipindah ke teras dan terkena percikan hujan. Dua tutup mengembang, membuat pembeli meminta potongan kecil. Ketika Sari mencari perintah tentang jalur tengah pada surat pemeriksaan, ia hanya menemukan tanggal dan kolom sanksi yang kosong. Bau ikan lembap memenuhi seluruh teras.'] },
      { chapterNumber: 41, title: 'Surat Kolom Kosong', paragraphs: ['Surat pemberitahuan ditempel di dinding loket memuat tanggal pemeriksaan gudang, sementara kolom sanksi dibiarkan kosong oleh penulisnya. Sari membaca dua kali untuk memastikan. Bu Hasnah bertanya apakah perlu memindahkan karung, dan Sari tidak dapat menjawab. Tanggalnya jelas, isi ancamannya tidak.'] },
      { chapterNumber: 42, title: 'Rak Depan Dikosongkan', paragraphs: ['Bu Hasnah akhirnya memerintahkan rak depan dikosongkan seluruhnya. Empat buruh lembur sampai tengah malam, lalu salah satu lampu minyak pecah. Api padam sebelum menyentuh karung, tetapi kain penutup hangus. Gudang membeli pengganti dengan uang makan dua hari. Asap tipis tertinggal dekat langit-langit gudang.'] },
      { chapterNumber: 43, title: 'Kolom Masih Kosong', paragraphs: ['Menjelang tanggal tersebut kolom sanksi tetap dibiarkan kosong meskipun surat diperbarui dengan cap lilin biru. Sari menghabiskan dua malam memindahkan karung ke rak belakang untuk berjaga. Tenaganya benar-benar terpakai. Namun tidak seorang pun tahu apakah karung di rak depan akan disita, didenda, atau sekadar dihitung ulang.'] },
      { chapterNumber: 44, title: 'Petugas Mengukur Pintu', paragraphs: ['Seorang petugas datang lebih awal hanya untuk mengukur lebar pintu dan tinggi rak. Ia tidak membuka karung. Sari bertanya apa yang akan terjadi pada tumpukan belakang, tetapi lelaki itu menyuruhnya membaca surat. Bu Hasnah membatalkan satu kiriman agar lorong tetap kosong.'] },
      { chapterNumber: 45, title: 'Malam Tanpa Tidur', paragraphs: ['Malam terakhir dipakai Sari mengecek setiap simpul karung. Bu Hasnah tertidur di bangku dengan buku sewa di pangkuan. Mereka sudah membayar kain, meja, pengganti buruh, dan kiriman batal. Menjelang fajar, kolom pada surat masih kosong seperti saat pertama ditemukan. Ayam berkokok sebelum hitungan selesai.'] },
      { chapterNumber: 46, title: 'Pemeriksaan Berlangsung Singkat', paragraphs: ['Pemeriksaan berlangsung setengah jam, petugas menghitung sebagian rak lalu menandatangani lembar hadir. Tidak ada karung dibawa, tidak ada denda dibacakan, dan kolom sanksi pada arsip tetap kosong. Sari kehilangan dua malam tidur untuk sebuah tanggal yang datang dan pergi tanpa memperlihatkan taringnya.'] },
      { chapterNumber: 47, title: 'Karung Dikembalikan Depan', paragraphs: ['Buruh mengembalikan karung ke rak depan sepanjang pagi. Satu jahitan robek akibat terlalu sering dipindah, menumpahkan garam segenggam. Bu Hasnah menyapu butiran itu ke baskom. Kantor tidak mengirim hasil selain lembar hadir yang telah ditandatangani. Baskom garam ditaruh dekat dapur.'] },
      { chapterNumber: 48, title: 'Tagihan Persiapan Dijumlah', paragraphs: ['Sari menjumlah kain, meja, upah tambahan, dan potongan kiriman pada halaman belakang buku gudang. Setelah angka terakhir dijumlah, Bu Hasnah mengambil hasil tiga hari dari kaleng laba; kantong modal bulan depan tetap terikat. Bu Hasnah melipat surat pemeriksaan dan menyimpannya untuk menanyakan penggantian biaya, tanpa menunggu jawaban dari kantor. Angka terakhir digaris sebanyak dua kali.'] },
      { chapterNumber: 49, title: 'Permohonan Biaya Diterima', paragraphs: ['Loket menerima permohonan penggantian biaya lalu memberi nomor antrean. Petugas berkata jawaban mungkin datang setelah musim pasang. Bu Hasnah tidak diminta membayar lagi. Ia membuka kiriman normal dan memanggil kembali buruh yang sempat dipulangkan selama persiapan. Nomor antrean disimpan dalam buku gudang.'] },
      { chapterNumber: 50, title: 'Lorong Gudang Normal', paragraphs: ['Lorong gudang kembali dipenuhi gerobak. Bekas kapur masih terlihat pada rak, namun petugas tidak datang mengulang pemeriksaan. Sari menutup buku biaya dan mulai mencatat muatan baru. Bu Hasnah menyelipkan tagihan kain ke buku biaya, lalu menyerahkan kunci gudang kepada buruh yang menarik gerobak pertama. Roda gerobak menghapus bekas kapur.'] },
    ], justification: 'Bab 33–50 supplies a firm inspection date and triggers overtime, supplies, a replacement worker, damaged goods, and one cancelled shipment. Yet the blank sanction field never gains content; inspection takes thirty minutes, removes nothing, and leaves operations intact.' },
    { chapters: [
      { chapterNumber: 33, title: 'Jadwal Angin Dibicarakan', paragraphs: ['Kepala sandar menyebut rotasi feri akan ditinjau setelah angin timur berbalik. Latif menanyakannya lagi, tetapi jawaban hanya “mungkin”. Sari mencatat pengeluaran rumah di balik karcis lama. Mereka tetap membeli beras pekan itu, sambil mengurangi uang untuk minyak lampu. Karcis lama dilipat masuk kaleng.'] },
      { chapterNumber: 34, title: 'Sepatu Retak Disimpan', paragraphs: ['Sol sepatu Latif retak ketika turun dari feri. Ia berniat membeli pengganti, lalu mengurungkan niat setelah mengingat rotasi. Sari menjahit sol dengan benang layar. Sepatu masih dapat dipakai untuk trayek pagi, meski air merembes saat ia menginjak geladak basah. Benang hitam menahan sol sepanjang pagi.'] },
      { chapterNumber: 35, title: 'Atap Menetes Lagi', paragraphs: ['Hujan membuat atap dapur menetes ke dekat tungku. Tukang menawarkan perbaikan dua hari, namun Sari menyimpan uangnya karena jadwal Latif belum pasti. Mereka menaruh baskom di lantai. Tetesan memadamkan api sekali, lalu makan malam selesai lebih lambat tanpa kerusakan lain.'] },
      { chapterNumber: 36, title: 'Pesan Kepala Sandar', paragraphs: ['Seorang anak membawa pesan agar Latif siap terhadap perubahan sesudah akhir bulan. Tak ada kertas atau rincian trayek. Ia meminta giliran tambahan sebelum tanggal itu, tetapi kepala sandar mengatakan semua tempat penuh. Sari menghapus rencana membeli minyak lampu kedua dari daftar belanja.'] },
      { chapterNumber: 37, title: 'Upah Disimpan Separuh', paragraphs: ['Separuh upah Latif dimasukkan ke kain simpul di bawah tikar. Sisanya cukup untuk beras, ikan, dan obat sederhana. Sari menolak ajakan Ratih mengganti tirai rumah. Angin malam masuk melalui anyaman lama, tetapi keluarga masih tidur tanpa perlu meminjam uang. Tikar itu digelar kembali sebelum lampu dimatikan.'] },
      { chapterNumber: 38, title: 'Nama Belum Dipindah', paragraphs: ['Sari memeriksa papan awak dan melihat nama Latif tetap pada pagi hari. Kepala sandar berkata daftar baru masih dibahas. Mereka membeli satu botol minyak, bukan dua, lalu pulang berjalan kaki untuk menghemat karcis. Kaki Latif lecet karena sol jahitan bergeser.'] },
      { chapterNumber: 39, title: 'Dua Awak Akan Dipindah', paragraphs: ['Kepala sandar menempel pemberitahuan bahwa dua dari enam awak pagi akan dipindahkan ke hari lain pada rotasi berikutnya, tanpa mengumumkan nama. Latif salah satu dari enam awak itu. Sari menunda membayar tukang atap. Saat hujan berikutnya, satu ikat kayu bakar basah dan harus dijemur sebelum digunakan.'] },
      { chapterNumber: 40, title: 'Belanja Dipangkas Lagi', paragraphs: ['Mereka menyusun belanja sepekan dengan menghapus gula, kain baru, dan ongkos perahu. Latif masih menerima upah biasa. Sari menyimpan selisih di kaleng kecil, meski belum tahu berapa banyak pendapatan yang mungkin hilang. Tidak ada tanggal pengumuman tertulis pada papan. Daftar pendek itu digantung dekat tungku.'] },
      { chapterNumber: 41, title: 'Rotasi Mungkin Berubah', paragraphs: ['Latif diberi tahu bahwa rotasi awak feri mungkin berubah setelah musim angin. Kata mungkin diucapkan dua kali oleh kepala sandar. Sari mulai menghitung ulang penghasilan rumah seandainya trayek pagi hilang. Kemungkinan tersebut cukup besar untuk mengubah cara mereka membelanjakan upah, walau belum tercantum di kertas mana pun.'] },
      { chapterNumber: 42, title: 'Kain Atap Tak Dibeli', paragraphs: ['Pedagang menawarkan kain terpal yang cukup menutup dapur, tetapi Sari melewatinya. Harga itu setara simpanan rotasi. Malamnya hujan masuk melalui anyaman dan membasahi sekantong arang. Mereka masih punya kayu untuk memasak, sedangkan nama Latif belum berpindah dari papan. Arang basah menodai lantai dapur.'] },
      { chapterNumber: 43, title: 'Daftar Belum Ditempel', paragraphs: ['Daftar rotasi baru dikabarkan sudah disusun, tetapi belum ditempel di papan. Latif menahan diri membeli sepatu kerja dan Sari menunda memperbaiki atap dapur. Keduanya hidup dengan pengeluaran yang ditekan selama berminggu-minggu. Bentuk perubahan itu masih tidak diketahui, termasuk apakah namanya benar-benar tercantum di sana.'] },
      { chapterNumber: 44, title: 'Amplop Ternyata Upah', paragraphs: ['Kepala sandar menyerahkan amplop tertutup kepada Latif. Mereka membukanya di rumah dan menemukan rincian upah biasa, bukan rotasi. Sari tertawa lega sejenak, lalu melihat atap menetes ke tikar. Uang tetap disimpan karena papan baru dijanjikan dua hari lagi. Kertas rincian dilipat dekat kaleng.'] },
      { chapterNumber: 45, title: 'Dua Hari Bertambah', paragraphs: ['Dua hari berlalu dan papan belum diganti. Latif bertanya, mendapat jawaban bahwa catnya belum kering. Ia berjalan dengan sepatu yang semakin renggang pada tumit. Sari membeli lem murah untuk menahannya, mengurangi simpanan hanya satu keping. Lem mengering selama feri menyeberang.'] },
      { chapterNumber: 46, title: 'Papan Tetap Lama', paragraphs: ['Papan sandar akhirnya diperbarui, dan susunannya nyaris sama dengan yang lama kecuali dua nama yang bertukar hari. Latif tetap di trayek pagi. Uang yang ditahan selama musim itu telah membuat dapur mereka sempit, sedangkan ancaman yang menyebabkannya tidak pernah menjelma menjadi kehilangan.'] },
      { chapterNumber: 47, title: 'Sepatu Baru Dibeli', paragraphs: ['Latif membeli sepatu setelah memastikan namanya tetap. Harga naik dua keping sejak pertama dilihat, sehingga mereka mengambil sedikit dari uang atap. Ia membuang sepatu jahitan yang berbau air laut. Pekerjaannya berlanjut pada feri pagi dengan upah semula. Sol barunya mencengkeram geladak basah.'] },
      { chapterNumber: 48, title: 'Tukang Menilai Atap', paragraphs: ['Tukang memeriksa dapur dan menemukan tiga bilah bambu lapuk, bukan satu seperti perkiraan awal. Simpanan mereka cukup untuk mengganti dua. Ia memasang tambalan sementara pada bagian ketiga. Sari membayar tanpa berutang, tetapi harus menunggu upah berikutnya untuk membeli arang. Tambalan bergetar ketika angin datang.'] },
      { chapterNumber: 49, title: 'Arang Dipinjam Tetangga', paragraphs: ['Hujan membasahi kayu sebelum upah berikutnya datang. Sari meminjam sekeranjang arang dari tetangga dan berjanji menggantinya hari Jumat. Makan malam tetap matang. Latif menunjukkan karcis jadwal pagi esok, tanpa potongan trayek maupun perubahan tanggung jawab. Keranjang kosong dikembalikan sore berikutnya.'] },
      { chapterNumber: 50, title: 'Simpanan Kembali Terbuka', paragraphs: ['Upah Jumat mengisi kaleng setelah utang arang dibayar. Sari menyisihkan uang untuk bilah atap terakhir. Latif menggantung sepatu baru dekat pintu dan memeriksa jadwal pekan depan yang masih sama. Bilah terakhir baru dapat dipesan setelah upah Jumat; nama Latif masih tercetak pada trayek pagi pekan depan. Bilah bambu dipesan sebelum hujan baru.'] },
    ], justification: 'Bab 33–50 makes an uncertain rotation announcement constrain food, lamp oil, footwear, transport, and roof repairs, causing leaks, wet fuel, blisters, and small price increases. Latif ultimately retains the same morning route and wage, so losses stay domestic and limited.' },
  ],
}
